(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["coding"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-codemem-ast-guided-adaptive-memory-f-2026"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-1\">一 · 一个真实在线服务现场：补丁轮次里的 KV 账本</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-2\">二 · 旧方案一：检索式整段注入，显存与注意力的双重稀释</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-3\">三 · 旧方案二：固定窗口截断，依赖链在边界处断裂</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-4\">四 · 旧方案三：前缀缓存的命中率随编辑塌陷</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-5\">五 · 批调度的连带退化：变长打包与显存碎片</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-6\">六 · 为什么非改不可：三个不可回避的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-7\">七 · 请求到达时的长度分布与它的真实形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-8\">八 · 并发形态：多会话独立记忆状态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-9\">九 · 批大小与变长打包：AST 拓扑序的约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-10\">十 · SLO 的两类约束与驻留比例的旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-11\">十一 · 长尾：编辑跨多子树时的失效放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-12\">十二 · 负载塑造方案，方案反过来限制负载</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-13\">十三 · 驻留状态如何反向约束负载：打包粒度、失效半径与 SLO 标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-14\">十四 · 从 KV 驻留到 kernel 选择：两级供给的算力账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-15\">十五 · 数据类型阶梯：FP16/BF16、FP8、NVFP4 各自的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-16\">十六 · 累加精度与误差：分数排序为何不能被量化污染</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 在两级供给中的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-18\">十八 · 编辑失效后的重算路径：精度与失效粒度的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-19\">十九 · 精度档位与硬件档位的标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-20\">二十 · 显存账本的三个抽屉：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-21\">二十一 · 带宽瓶颈的位置：预填看算力，解码看 HBM</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-22\">二十二 · 分页、压缩、复用、卸载：四种手段的代价面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-23\">二十三 · 一个可复算的显存预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-24\">二十四 · 失效粒度与预算竞争的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-25\">二十五 · 按硬件档位标定驻留比例</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-26\">二十六 · 驻留预算的边界：AST 记忆在显存账本上的失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-27\">二十七 · 连续批处理在 AST 驻留状态上的重定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-28\">二十八 · Chunked prefill 与两级上下文供给的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-29\">二十九 · 优先级、抢占与摘要节点的降级路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-30\">三十 · 分离式预填/解码与子树失效的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-31\">三十一 · 尾延迟的压缩点与 SLO 标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-32\">三十二 · 节点驻留状态驱动的变长打包：调度边界与失效代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-33\">三十三 · 并行拓扑：CodeMEM 的 AST 记忆状态放在哪张卡上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-34\">三十四 · NVLink 5 与 NVSwitch：域内带宽决定 All-Reduce 是否可见</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-35\">三十五 · All-to-All 与 EP：MoE 路由与 AST 子树亲和性的冲突</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-36\">三十六 · NIXL 传输：跨节点 KV 搬运与子树失效的粒度匹配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-37\">三十七 · 通信何时成为瓶颈：三个可判定的信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-38\">三十八 · 并行切分下节点驻留的通信代价与失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-39\">三十九 · 精度塌陷：从“分数排序”到“预算挤兑”的静默失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-40\">四十 · OOM 与批抖动：变长打包的两种崩溃形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-41\">四十一 · 尾延迟：AST 预处理与摘要重算的叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-42\">四十二 · 静默降级：分数更新滞后与缓存假命中</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-43\">四十三 · 回滚：子树级失效的边界与保守策略</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-44\">四十四 · 失效链诊断：从分数漂移到子树失效放大</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-45\">四十五 · 评测口径的三层锚点：模型、硬件档位、负载形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-46\">四十六 · 指标族：TTFT、TPOT、吞吐、显存、功耗各自度量什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-47\">四十七 · batch 与并发：变长打包如何改变可比性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-48\">四十八 · 哪些提升不可比：四类典型错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-49\">四十九 · 数字怎么读：从机制到可核验量的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-50\">五十 · 迁移到非代码领域：AST 锚点消失后还剩什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-51\">五十一 · 迁到别的模型：KV 布局与失效粒度的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-52\">五十二 · 规模上限：解析开销与预算竞争的交叉点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-53\">五十三 · 编辑形态的边界：单子树假设何时破产</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-54\">五十四 · 硬件档位与精度选择对驻留比例的反向约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-55\">五十五 · 不适用的场景与迁移检查清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-56\">五十六 · 迁移边界：AST 记忆方案在何种模型与仓库形态下失效</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:561px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 560.8 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"478.8\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求到达时解析当前仓库快照，构建 AST 依赖图并标注跨文件定义—调用…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"478.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按依赖入度、历史引用频次与编辑距离为每个 AST 节点计算记忆价值分数。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"478.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">依分数在 KV 预算内选择完整驻留节点与摘要节点，生成预填序列并做变长…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"478.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">预填阶段对完整节点复用前缀缓存 KV，对摘要节点重算少量 token …</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"478.8\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">解码阶段生成补丁，编辑落地后按 AST 差异只失效受影响子树的 KV …</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"478.8\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">下一轮迭代复用未失效 KV，并按新引用更新节点价值分数与驻留状态。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-1\">一 · 一个真实在线服务现场：补丁轮次里的 KV 账本</h3>\n<p>设想一个托管在 GB200 NVL72 机架上的仓库级编码助手，服务对象是一个中等规模的后端仓库：几十个包、数百个源文件、跨文件调用边密集。用户会话不是“问一次答一次”，而是迭代式修补：先让模型改一个工具函数，再让它同步三处调用点，随后追加边界检查、补测试、修类型。每一轮请求都要把当前仓库快照里相关的定义—调用链塞进提示，模型产出补丁，补丁落地，下一轮再来。工程上最刺眼的不是模型能力，而是这条循环里 KV cache 的账本：轮次越多，历史上下文越长，KV 随轮次近似线性膨胀；而每次编辑都让前缀缓存的有效区间从编辑点之后整段作废。批调度器看到的是长度参差、前缀各异的序列，填充 token 与显存碎片一起上涨，吞吐被拖垮，首 token 延迟（TTFT）在多会话并发下抖动。</p>\n<p>这就是 CodeMEM 要处理的现场：跨轮上下文复用与 KV 显存预算之间的正面冲突。旧方案在这个现场里不是“不够聪明”，而是账算不过来——要么全量保留，KV 爆炸、批调度退化；要么粗粒度截断，定义—调用链被切断，模型拿到的是残缺语义。下面把旧方案拆开看它的代价结构，再说明为什么非改不可。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-2\">二 · 旧方案一：检索式整段注入，显存与注意力的双重稀释</h3>\n<p>主流做法之一是检索增强式上下文注入：用嵌入或符号索引召回相关文件、函数，把整段源码拼进提示。机制上它简单可落地，但代价结构很糟。第一，召回粒度是文件或函数整段，一个被三处调用的工具函数会把整个文件体连同无关语句一起塞入，KV 占用按整段计；第二，注意力被稀释——真正决定补丁正确性的往往只是签名、几条调用边和最近的编辑差异，但它们在长提示里与大量无关 token 竞争注意力权重；第三，预填阶段要为新拼入的整段做全量前向，前缀缓存只在提示前缀完全一致时命中，而检索结果随轮次变化，命中率天然低。</p>\n<p>用代价语言写清楚：设一轮提示 token 数为 <span>L</span>、层数为 <span>d</span>、KV 头维度为 <span>h</span>，则单会话 KV 显存近似正比于 <span>L·d·h</span>；当并发会话数为 <span>N</span> 时，KV 池需求是 <span>N</span> 倍。整段注入把 <span>L</span> 推高，直接压缩可并发的批大小，而批大小又决定了解码阶段的吞吐。更隐蔽的是填充浪费：变长序列打包时，长短不一的整段注入让 padding token 占比上升，算力花在无效位置上。</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}} \\approx N \\cdot L \\cdot d \\cdot h \\cdot b,\\qquad \\text{throughput} \\propto \\frac{B_{\\mathrm{batch}}}{L_{\\mathrm{eff}}}$$</div>\n<p>具体例子：一次“改工具函数并同步三处调用点”的请求，检索式方案可能召回该函数所在文件、三个调用点所在文件、以及导入链上的两个模块，提示长度被推到远超必要的水位；其中真正被引用的语句只占很小比例，其余都是稀释项。工程判断很直接：在 Blackwell 档位上，KV 池是稀缺资源，按整段注入等于用显存买冗余。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-3\">三 · 旧方案二：固定窗口截断，依赖链在边界处断裂</h3>\n<p>另一条路是固定窗口截断：只保留最近 <span>W</span> 个 token，或按“最近编辑优先”滑动窗口。它的显存账好看，KV 上限被硬约束，批调度也稳定。但它把语义结构当成了平坦的 token 流，截断点与 AST 边界无关。定义—调用链一旦跨过窗口边界，模型看到调用点却看不到定义，或看到定义却丢失调用上下文，补丁就会引入签名不匹配、漏改调用点这类错误。更糟的是，截断策略与编辑位置脱钩：用户改的是文件 A 的函数，但窗口按时间顺序保留的是文件 B 的近期内容，相关性判断完全失效。</p>\n<p>代价上，固定窗口把“显存可控”换成了“语义不可控”。它的失败不是延迟问题，而是正确率问题——在仓库级迭代生成里，一次漏改调用点的补丁会触发下一轮返工，返工又拉长会话轮次，反过来推高总 KV 压力。这是一个负反馈：截断省下的显存，被返工轮次吃掉。伪代码层面，旧策略大致是“按 token 计数从尾部取窗口”，没有任何结构信号参与决策：</p>\n<ul>\n<li>输入：历史提示 token 流、当前编辑位置；</li>\n<li>规则：保留尾部 <span>W</span> 个 token，其余丢弃；</li>\n<li>后果：窗口边界与函数/类边界不对齐，跨文件调用边被随机切断；</li>\n<li>系统代价：单轮显存可控，但返工率上升导致会话总轮次与总预填量增加。</li>\n</ul>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-4\">四 · 旧方案三：前缀缓存的命中率随编辑塌陷</h3>\n<p>前缀缓存本是推理栈里最划算的优化：相同提示前缀的 KV 直接复用，只对新增后缀做预填。但在迭代式仓库编辑里，它的前提被破坏。用户每轮落地一个补丁，提示中位于编辑点之后的上下文全部变化；如果缓存按“整段前缀”做键，编辑点之前的 KV 尚可复用，编辑点之后整段失效。问题在于旧方案的上下文拼接顺序往往与 AST 结构无关——按检索分数、按文件字典序、按时间顺序——于是编辑点在前缀中的位置漂移，命中区间被切得很碎。命中率随编辑下降，预填量随轮次回升，TTFT 在多会话并发下出现尖峰。</p>\n<p>把命中率写成可算的量：设一轮提示长度为 <span>L</span>、可复用前缀长度为 <span>\\(L_{\\mathrm{hit}}\\)</span>，则预填计算量正比于 <span>\\(L - L_{\\mathrm{hit}}\\)</span>；编辑导致 <span>\\(L_{\\mathrm{hit}}\\)</span> 塌缩时，预填成本回到接近全量。旧方案的失效粒度是“整段”，一次函数体内的编辑会让整段后续上下文重算，哪怕其中大部分节点与编辑无关。这就是 CodeMEM 后来引入“按 AST 差异做子树级增量失效”的直接动机——但那是后续部分的话题，此处只需看清旧方案的代价：失效粒度过粗，重算量与实际语义变化量不匹配。</p>\n<div class=\"formula\">$$C_{\\mathrm{prefill}} \\propto (L - L_{\\mathrm{hit}}) \\cdot d \\cdot h,\\qquad L_{\\mathrm{hit}} \\text{ 随编辑次数单调下降}$$</div>\n<p>具体例子：同一会话第二轮追加“再补一个边界检查”，编辑只触及函数体几行，但旧方案下编辑点之后的调用点上下文、导入段、测试片段全部重算；若并发有数十个会话同时在做类似编辑，预填队列会把解码阶段的算力挤占，SLO 的低延迟补全目标首先失守。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-5\">五 · 批调度的连带退化：变长打包与显存碎片</h3>\n<p>旧方案的第三个代价不在单会话，而在批调度层。连续批处理依赖变长序列打包来摊薄填充浪费，但打包效率取决于序列长度的分布是否稳定。检索式整段注入让长度分布随召回结果剧烈波动；固定窗口虽然长度稳定，却让语义残缺；前缀缓存塌陷则让“已缓存前缀 + 新增后缀”的实际计算长度不可预测。三者叠加，批调度器要么保守地按最长序列预留显存，造成碎片；要么频繁重打包，引入调度开销。在 Blackwell 的 2-SM MMA 与 tcgen05 路径上，算力利用对批内序列的规整度敏感，填充 token 比例上升直接压低有效算力占比。</p>\n<p>这里要区分两类浪费：一类是显存浪费（KV 池被低价值上下文占据），一类是算力浪费（填充位置与重算前缀）。旧方案在两类浪费上同时失分，因为它们都缺少一个“按语义价值分配预算”的决策变量。CodeMEM 的切入点正是把这个变量显式化：以 AST 节点为记忆单元，按依赖入度、跨轮引用次数与编辑距离打分，在 KV 预算内区分完整驻留与摘要驻留——分数形式为</p>\n<div class=\"formula\">$$s(n)=\\alpha\\,\\mathrm{indeg}(n)+\\beta\\,\\mathrm{ref}(n)+\\gamma\\,e^{-\\delta\\,\\mathrm{dist}(n)},\\quad \\sum_{n\\in R}s(n)\\le B_{\\mathrm{KV}}$$</div>\n<p>旧方案没有这个排序问题，只有“留或扔”的二选一，于是预算无法按 SLO 调节。工程上的非改不可，就落在这一点：仓库级迭代生成的上下文价值高度不均，少数节点承载定义—调用链，多数节点只是背景；用统一粒度处理必然在显存与语义之间二选一，而在线服务两个都不能丢。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-6\">六 · 为什么非改不可：三个不可回避的约束</h3>\n<p>把旧方案的痛点收敛成三条工程约束。其一，显存预算硬约束：KV 池容量由硬件档位决定，B200/B300 单机与 GB200 NVL72 机架的可用显存不同，部署时必须按档位标定驻留比例；全量保留在多会话并发下直接越界，粗粒度截断则把语义损失转嫁给正确率。其二，前缀缓存必须与编辑对齐：编辑事件频繁是这类负载的固有形态，失效粒度若停留在整段，重算量随轮次累积，TTFT 无法满足低延迟补全 SLO。其三，批调度需要可预测的长度分布：变长打包的效率依赖上下文拼接顺序的稳定性，而拼接顺序应当由结构决定，而非由检索分数或时间顺序随机决定。</p>\n<p>这三条约束共同指向一个判断：KV 管理不能停留在“截断或全留”的二选一，必须变成结构感知的预算分配问题。旧方案的失败模式也很清楚——把上下文价值当作静态优先级、忽略编辑后引用变化导致的驻留升降级，缓存命中率会持续下降；摘要与完整的比例若没有按 SLO 标定，重算成本会侵蚀缓存收益；跨多子树编辑时若仍按单子树假设估算重算量，会低估迭代轮次的实际延迟。CodeMEM 把记忆单元细化到 AST 四级节点（文件—类—函数—语句），让预算约束落在节点分数之和上，并把编辑后的失效范围收敛到受影响子树——这是把显存代价与语法依赖显式挂钩的第一步。对部署者而言，这意味着可以在 Blackwell 档位上按 SLO 调节驻留比例与摘要比例，而不是在“爆显存”和“丢依赖”之间被动摇摆。</p>\n<p>具体到一个可操作的现场标定：监控项应包含前缀缓存命中率、摘要重算 token 占比与失效子树规模；当命中率随编辑下降而重算占比上升时，说明摘要比例或失效粒度需要调整，而不是简单加大批大小。AST 解析与依赖图构建是请求前置步骤，超大仓库下的预处理延迟未在材料中量化，部署时需把它计入 TTFT 预算，避免解析开销吃掉缓存收益。这些代价在旧方案里根本无从谈起，因为它们连“按节点分配预算”这个旋钮都不存在。</p>\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-7\">七 · 请求到达时的长度分布与它的真实形状</h3>\n<p>仓库级迭代生成的单轮请求不是一条均匀长度的序列，而是三段拼接：系统提示与工具描述、跨文件定义—调用片段、历史修改摘要。CodeMEM 把第一段视为稳定前缀，第二段按 AST 节点分数排序后拼接，第三段随轮次增长。长度分布的关键不在均值而在分位：函数级节点通常只携带签名与少量语句，文件级节点携带导入与类声明，跨文件调用链则可能把两三个文件的片段串起来。单轮提示长度因此呈现双峰——多数轮次只触及单文件局部修改，少数轮次因跨模块重构而拉出长链。</p>\n<p>这个分布直接决定预填阶段的代价结构。预填计算量近似为</p>\n<div class=\"formula\">$$T_{\\mathrm{prefill}} \\approx \\sum_{i \\in \\mathcal{N}_{\\mathrm{full}}} L_i \\cdot c_{\\mathrm{reuse}} + \\sum_{j \\in \\mathcal{N}_{\\mathrm{sum}}} L_j \\cdot c_{\\mathrm{recalc}}$$</div>\n<p>其中完整驻留节点的每 token 代价由前缀缓存命中压低，摘要节点则要重新走前向。长尾请求的伤害不在它自己，而在它把批内其他短请求的打包效率拖低：一个跨三文件的请求与五个单函数请求同批，变长打包后填充比例上升，显存占用按最长序列对齐。工程上的判断是给长度分位设阈值，超过阈值的请求走单独批次或降级为摘要比例更高的驻留策略，而不是让整批陪跑。</p>\n<p>具体例子：一次“把日志工具改成结构化输出”的请求，触及工具函数、两处调用点与一个配置文件，AST 图拉出的节点集合跨越三个文件；若与四个只改注释的请求同批，填充 token 比例被最长序列主导，短请求的有效吞吐被稀释。测量口径应记录每批的 <em>实际 token 数 / 打包后 token 数</em>，以及按长度分位（如 p50/p90/p99）分桶的批大小分布，而不是只报平均批大小。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-8\">八 · 并发形态：多会话独立记忆状态</h3>\n<p>并发不是简单的请求数，而是会话数乘以每会话的驻留集合。每个会话维护独立的 AST 记忆状态与 KV 驻留集合，两个会话即使改同一个仓库，节点分数也因各自引用历史不同而分叉。这意味着 KV 预算不能在会话间简单共享：A 会话把某函数节点升为完整驻留，B 会话可能只保留摘要，同一份前缀缓存条目被两种粒度引用。前缀缓存的键必须包含驻留状态，否则摘要节点会错误命中完整 KV。</p>\n<p>并发上升时，显存压力来自驻留集合的并集而非单会话峰值。设会话 <em>k</em> 的驻留集合为 <em>R<sub>k</sub></em>，总占用近似为</p>\n<div class=\"formula\">$$M_{\\mathrm{KV}} \\approx \\sum_{k} \\sum_{n \\in R_k} \\big[\\, \\mathbb{1}_{\\mathrm{full}}(n)\\, V_n + \\mathbb{1}_{\\mathrm{sum}}(n)\\, v_n \\,\\big]$$</div>\n<p>其中 <em>V<sub>n</sub></em> 是节点完整 KV 体积，<em>v<sub>n</sub></em> 是摘要 token 体积。并集里重复节点的 KV 若不做跨会话共享，显存随并发线性增长；若做共享，又要处理两个会话对同一节点不同驻留状态的冲突。可行的折中是按节点粒度做引用计数，完整驻留的节点在会话间共享同一份 KV，摘要节点各自持有轻量副本。</p>\n<p>代价落在调度侧：并发越高，批调度器越难把驻留状态相近的请求聚成一批，变长打包的填充浪费与显存碎片同时上升。测量口径应记录并发会话数、跨会话共享 KV 条目的命中次数、以及每会话驻留集合的并集大小随时间的变化；只报 QPS 会掩盖显存随会话数增长的真实斜率。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-9\">九 · 批大小与变长打包：AST 拓扑序的约束</h3>\n<p>批调度器按节点驻留状态打包变长序列，但打包粒度受 AST 拓扑序约束：预填序列必须按依赖顺序拼接，定义节点排在被调用节点之前，否则注意力看到的上下文顺序与语法依赖不一致。这带来一个调度上的硬约束——不能为了填满批次而任意重排节点，只能在拓扑序允许的范围内做打包。结果是批内序列长度的方差被结构放大，填充 token 比例高于纯文本推理的连续批处理。</p>\n<p>打包效率可写成</p>\n<div class=\"formula\">$$\\eta_{\\mathrm{pack}} = \\frac{\\sum_{i} L_i}{\\,B \\cdot \\max_i L_i\\,}$$</div>\n<p>分母是按最长序列对齐后的容量。当批内混入一个跨文件长链请求，<em>max<sub>i</sub> L<sub>i</sub></em> 被拉高，<em>η</em> 骤降。CodeMEM 的应对是按驻留状态分层打包：完整驻留节点多的请求与摘要节点多的请求分开成批，因为前者预填便宜、后者重算贵，混在一起会让批的代价由最贵的那条决定。分层打包的代价是批大小变小、批次数变多，调度开销上升。</p>\n<p>具体例子：五个请求中有三个只改单函数、两个跨文件重构。若按到达顺序打包，最长序列决定对齐长度，三个短请求的填充比例超过其有效 token；若按驻留状态分成两批，短请求批的 <em>η</em> 接近满，长请求批单独承担高重算代价。测量口径应记录每批的 <em>η</em>、批内序列长度方差、以及分层打包前后的批次数与端到端延迟分布。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-10\">十 · SLO 的两类约束与驻留比例的旋钮</h3>\n<p>负载的 SLO 不是单一指标。低延迟补全类请求关心首 token 时间，中等吞吐批处理关心每 token 吞吐，两者对驻留比例的要求相反：提高完整驻留比例降低预填重算、压低首 token 延迟，但抬高显存占用、压缩可并发会话数；提高摘要比例省显存、抬吞吐，但摘要重算引入额外前向，首 token 延迟上升。CodeMEM 把驻留比例当作显式旋钮，正是为了让 SLO 与显存预算在同一坐标系里取舍。</p>\n<p>设完整驻留节点占比为 <em>ρ</em>，则首 token 延迟可定性分解为解析延迟、预填延迟与重算延迟三部分，预填延迟随 <em>ρ</em> 上升而下降，重算延迟随 <em>ρ</em> 下降而上升。存在一个使总延迟最小的 <em>ρ</em>，但它随仓库规模与摘要 token 数量漂移，材料未给出该曲线的形状。工程上不能假设 <em>ρ</em> 有普适最优值，只能按硬件档位与 SLO 标定：低延迟档位把 <em>ρ</em> 推高，吞吐档位把 <em>ρ</em> 压低并接受重算。</p>\n<p>代价的另一面是 AST 解析与依赖图构建作为请求前置步骤，其延迟不随 <em>ρ</em> 变化，却在超大仓库上成为首 token 时间的固定底噪。低延迟补全的 SLO 若卡在百毫秒级，解析开销可能直接吃掉预算，此时需要把解析结果按仓库快照缓存、只对变更文件做增量解析。测量口径应把端到端延迟拆成解析、预填、解码三段分别记录，并记录 <em>ρ</em> 的实际取值与摘要重算 token 占比；只报端到端 P99 无法判断瓶颈在哪一段。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-11\">十一 · 长尾：编辑跨多子树时的失效放大</h3>\n<p>长尾请求的来源不是长度而是编辑范围。单子树编辑只失效一个节点的 KV，跨多子树编辑按 AST 差异失效多个子树，失效范围扩大直接抵消缓存收益。更麻烦的是失效与重算的耦合：失效的子树在下一轮要重新预填，若这些子树恰好是高分节点，重算量按完整 KV 体积计，而非摘要 token。长尾因此表现为迭代轮次延迟的尖峰，而不是单轮延迟的尖峰。</p>\n<p>失效放大可用失效节点集合的规模与总驻留集合规模之比刻画：</p>\n<div class=\"formula\">$$\\lambda_{\\mathrm{inv}} = \\frac{\\sum_{n \\in \\mathcal{I}} V_n}{\\sum_{n \\in R} V_n}$$</div>\n<p>其中 <em>ℐ</em> 是本轮失效子树集合。跨模块重构会让 <em>λ</em> 接近 1，退化为整段重算；局部修补让 <em>λ</em> 很小，缓存收益显著。工程判断是按 <em>λ</em> 设降级路径：<em>λ</em> 超过阈值时放弃增量失效、直接整段重算并重建驻留集合，因为逐子树失效的簿记开销在此时已超过重算本身。</p>\n<p>具体例子：一次“重命名公共接口并同步所有实现”的请求，AST 差异触及接口定义与多个实现文件，失效子树集合覆盖了大部分高分节点，<em>λ</em> 接近 1；此时按单子树假设估算重算量会严重低估迭代延迟。测量口径应记录每轮的失效子树数、失效 KV 体积、<em>λ</em> 的分布，以及降级路径触发次数；这些指标比命中率更能解释长尾延迟。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-12\">十二 · 负载塑造方案，方案反过来限制负载</h3>\n<p>双向塑造是这一部分的核心判断。负载塑造方案：长度双峰迫使方案做分层打包，编辑范围的长尾迫使方案做失效降级，多会话并发迫使方案做跨会话 KV 共享与引用计数。方案反过来限制负载：AST 拓扑序约束打包自由度，驻留比例旋钮约束可并发会话数，解析前置延迟约束低延迟请求的准入。部署时若无视这层反向约束，把并发推到显存上限，批调度退化为逐请求串行，吞吐反而低于中等并发。</p>\n<p>可核查的测量口径应成组给出，而非单点指标：按长度分位分桶的批大小与打包效率 <em>η</em>；按会话数记录的 KV 并集大小与共享命中次数；按轮次记录的失效比例 <em>λ</em> 与降级触发次数；端到端延迟拆成解析、预填、解码三段；以及驻留比例 <em>ρ</em> 与摘要重算 token 占比的联合分布。这五组指标共同回答一个问题——当前配置下，显存预算换来的缓存收益是否真的落在 SLO 内。缺少任何一组，调参就退化为对单一数字的盲试。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-13\">十三 · 驻留状态如何反向约束负载：打包粒度、失效半径与 SLO 标定</h3>\n\n<p>CodeMEM 的批调度器按节点驻留状态做变长序列打包，但打包粒度受 AST 拓扑序约束：同一函数节点下的语句节点必须连续排布，跨文件调用边又要求定义节点与调用节点在预填序列中保持相对次序。这意味着可打包的序列不是任意变长，而是被依赖图切分成若干“拓扑连通块”，块内填充浪费可控，块间则因完整驻留与摘要驻留混杂而产生显存碎片。设一轮请求的预填 token 总量为 <span class=\"formula\">$$T_{\\text{prefill}}=\\sum_{n\\in R_{\\text{full}}}L_n+\\sum_{n\\in R_{\\text{sum}}}L^{\\text{sum}}_n$$</span>，其中完整节点长度 <span class=\"formula\">$$L_n$$</span> 直接来自缓存、摘要节点长度 <span class=\"formula\">$$L^{\\text{sum}}_n$$</span> 需重算。批大小上限由 <span class=\"formula\">$$B_{\\text{KV}}$$</span> 与填充比例共同决定，填充比例升高时有效批大小下降，吞吐随之退化——这是方案对负载形态的第一重反向限制：它偏好“编辑集中、依赖链短”的请求，而对一次触及多文件多子树的宽编辑，连通块数量激增，打包收益被稀释。</p>\n\n<p>失效半径是第二重限制。子树级增量失效在单子树编辑时收益明确：仅该子树 KV 被丢弃，三处调用点节点继续驻留，下一轮预填只需重算被失效子树的少量 token。但跨多子树编辑时，失效集合按 AST 差异扩张，若仍按单子树假设估算重算量，会低估实际延迟。可核查的口径是定义“失效放大系数” <span class=\"formula\">$$\\rho=\\frac{\\sum_{n\\in R_{\\text{inv}}}L_n}{\\sum_{n\\in R_{\\text{edit}}}L_n}$$</span>，即失效节点 token 总量与直接编辑节点 token 总量之比；<span class=\"formula\">$$\\rho$$</span> 接近 1 说明失效精准，显著大于 1 则说明依赖边把失效拖到了未编辑子树。工程上应把 <span class=\"formula\">$$\\rho$$</span> 与摘要重算 token 占比一并纳入监控，前者刻画缓存收益的侵蚀，后者刻画额外前向开销。</p>\n\n<p>负载形态还通过并发会话数塑造方案边界。每会话维护独立 AST 记忆状态与 KV 驻留集合，多会话并行时 <span class=\"formula\">$$B_{\\text{KV}}$$</span> 需在各会话间切分，单会话可用预算下降会迫使更多节点降级为摘要驻留，摘要比例升高又推高重算成本，形成“并发—预算—重算”的耦合。低延迟补全类 SLO 对此尤其敏感：AST 解析与依赖图构建是请求前置步骤，超大仓库下该预处理延迟未量化，若解析耗时接近补全预算，则驻留策略再精细也无法满足首 token 时延。可核查的测量口径应包括：单轮预填 token 数与其中摘要重算占比、填充 token 比例、失效放大系数 <span class=\"formula\">$$\\rho$$</span>、前缀缓存命中率、AST 解析耗时占端到端延迟的比例，以及按硬件档位（B200／B300／GB200 NVL72）标定的 <span class=\"formula\">$$B_{\\text{KV}}$$</span> 与摘要 token 上限。分数权重与衰减系数为启发式设定且材料未给出数值，部署时须以这些口径做标定，而非把节点分数当作静态优先级——忽略编辑后引用变化导致的驻留升降级，正是缓存命中率下降的直接来源。</p>\n\n<table class=\"mini\"><thead><tr><th>负载特征</th><th>方案偏好</th><th>失效条件</th><th>代价落点</th></tr></thead><tbody><tr><td>编辑集中于单子树</td><td>失效半径小、<span class=\"formula\">$$\\rho\\approx1$$</span></td><td>跨文件调用边被同步修改</td><td>重算 token 少，延迟低</td></tr><tr><td>宽编辑触及多子树</td><td>连通块多、打包碎片高</td><td>按单子树估算重算量</td><td>填充比例与失效放大系数上升</td></tr><tr><td>高并发多会话</td><td>预算切分、摘要比例可控</td><td>解析延迟逼近补全 SLO</td><td>首 token 时延与重算前向叠加</td></tr></tbody></table>\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-14\">十四 · 从 KV 驻留到 kernel 选择：两级供给的算力账</h3>\n<p>CodeMEM 的推理层把预填序列切成两类节点：完整驻留节点直接复用前缀缓存中的 KV，摘要节点则要重算少量 token 并写回缓存。这一分层在算子层面立刻变成两种截然不同的计算形态——前者是纯访存（读 KV、拼 attention），后者是小规模 GEMM 加 attention 的混合。Blackwell 上的工程判断因此不是“用哪个 kernel”，而是“每类节点该走哪条精度路径”。完整驻留节点的 KV 已经以某种精度落盘在 HBM 或由前缀缓存持有，复用时不重新量化，读带宽决定延迟；摘要节点每次重算都要跑一遍 QKV 投影与 attention，算力与精度选择直接进入关键路径。若把两类节点塞进同一个批，kernel 会按最保守的精度配置执行，完整节点白白承担了它不需要的算力开销。可行的做法是按驻留状态分桶：完整节点桶只做 KV gather 与 attention，摘要节点桶走完整前向，两桶在批调度器里按变长打包拼接。代价是分桶带来的额外 kernel launch 与桶间同步，但相对混批的精度降级损失更可控。</p>\n<p>以一次仓库级修复请求为例：工具函数节点入度为三、跨文件引用两次，分数最高，分配完整 KV 驻留；其上游导入节点仅保留摘要 token。预填时完整节点命中前缀缓存，摘要节点重算十余 token。十余 token 的重算在 Blackwell 上是一个极小的 GEMM（M 很小、N 为 hidden），其效率几乎完全由 kernel launch 开销与权重读取带宽支配，而非 Tensor Core 吞吐。这意味着摘要路径的优化重点不是选更快的 MMA 形状，而是把多个摘要节点合并成一次 batched GEMM，减少 launch 次数。反过来，完整节点的 attention 是带宽受限的，KV 读取量正比于驻留 token 数与层数，精度每降一档，读带宽需求按位宽比例下降。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-15\">十五 · 数据类型阶梯：FP16/BF16、FP8、NVFP4 各自的位置</h3>\n<p>Blackwell 第五代 Tensor Core 支持从 FP16/BF16 到 FP8 再到 NVFP4 的窄精度路径，每降一档，理论算力上升、权重与激活的位宽下降。CodeMEM 的场景里，这三档不是替代关系而是分工关系。BF16 适合摘要节点的重算：重算 token 少、对数值稳定性敏感（代码 token 的 logits 分布尖锐，低精度累加容易翻转采样），且重算量小到算力不构成瓶颈，用 BF16 换数值确定性是划算的。FP8 适合完整驻留节点的 KV 存储与 attention：KV 读带宽是瓶颈，FP8 把 KV 位宽减半，直接缓解 HBM 压力，而 attention 的 softmax 对 KV 量化误差有一定容忍度。NVFP4 则适合权重侧——当摘要节点需要跑完整前向时，权重以 NVFP4 驻留可显著压缩权重读取量，但激活与 KV 仍应留在 FP8 或 BF16，因为代码生成的输出分布对激活量化更敏感。</p>\n<p>一个具体的分层配置：完整驻留节点的 KV 以 FP8 存储，attention 的 Q 用 BF16 计算以避免 softmax 溢出；摘要节点的权重用 NVFP4 解压后做 BF16 激活的 GEMM；两级之间不做精度统一。代价是显存里同时存在 FP8 KV、NVFP4 权重与 BF16 激活三种格式，显存管理复杂度上升，且跨精度转换（NVFP4 解压到 BF16）引入额外指令。收益是完整节点桶的 KV 读带宽按 FP8 位宽计，摘要节点桶的权重读取按 NVFP4 位宽计，两条路径各自压到自己的瓶颈上。若统一用 BF16，完整节点桶的 KV 读带宽翻倍，在长上下文仓库场景下直接体现为 prefill 延迟上升。</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>推荐精度</th><th>瓶颈</th><th>CodeMEM 中的角色</th></tr></thead><tbody><tr><td>完整驻留 KV + attention</td><td>KV FP8，Q BF16</td><td>HBM 读带宽</td><td>复用前缀缓存，不重算</td></tr><tr><td>摘要节点重算</td><td>权重 NVFP4，激活 BF16</td><td>权重读取 + launch 开销</td><td>十余 token 小 GEMM，合并批处理</td></tr><tr><td>输出头 / logits</td><td>BF16 累加</td><td>数值稳定性</td><td>代码 token 分布尖锐，不可窄化</td></tr></tbody></table>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-16\">十六 · 累加精度与误差：分数排序为何不能被量化污染</h3>\n<p>CodeMEM 的记忆价值分数是一个排序量，节点按分数在 KV 预算内竞争驻留资格。分数本身不进入模型前向，但它决定哪些节点被完整保留、哪些被摘要化——一次排序错误等价于一次上下文选择错误。分数公式为：</p>\n<div class=\"formula\">$$s(n)=\\alpha\\,\\mathrm{indeg}(n)+\\beta\\,\\mathrm{ref}(n)+\\gamma\\,e^{-\\delta\\,\\mathrm{dist}(n)},\\quad \\sum_{n\\in R}s(n)\\le B_{\\mathrm{KV}}$$</div>\n<p>逐项看：$\\mathrm{indeg}(n)$ 是 AST 依赖图中该节点的入度，即有多少定义—调用边指向它，整数计数，无量化误差；$\\mathrm{ref}(n)$ 是跨轮引用次数，同样是整数累加；$e^{-\\delta\\,\\mathrm{dist}(n)}$ 是编辑距离的指数衰减项，$\\mathrm{dist}(n)$ 为该节点自上次驻留以来被编辑的字符或 AST 差异量，$\\delta$ 控制衰减陡峭度。三项加权求和后与预算 $B_{\\mathrm{KV}}$ 比较，$\\sum_{n\\in R}s(n)\\le B_{\\mathrm{KV}}$ 表示被选中集合 $R$ 的分数总和不超过 KV 上限——这是一个背包约束，分数是排序键也是容量占用度量。前两项是整数，第三项是浮点指数，若用 FP16 计算 $e^{-\\delta\\,\\mathrm{dist}}$，在 $\\mathrm{dist}$ 较大时结果下溢到零，多个低价值节点分数并列，排序退化为按节点 ID 或遍历序，可能把本应淘汰的节点留在预算内。工程上这一项应在 FP32 下计算，或改用查表加整数近似，避免窄精度污染排序。</p>\n<p>累加精度在 attention 侧是另一回事。完整驻留节点的 KV 以 FP8 存储，attention 的 $QK^\\top$ 与 $PV$ 若在 FP8 下累加，softmax 前的 logits 误差会被指数放大。Blackwell 的 Tensor Core 支持 FP8 输入配更高精度累加，工程上应让 MMA 的累加器保持 FP32 或至少 BF16，仅输入窄化。代价是累加器位宽占用寄存器与 TMEM 容量，在 2-SM MMA 下累加器跨两个 SM 的 TMEM 分布，位宽翻倍直接压缩可并行的 tile 数。这是一个明确的权衡：FP32 累加换数值稳定，BF16 累加换 tile 并行度。对代码生成，采样温度低时 logits 微小误差即可翻转 token，应偏向前者。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-17\">十七 · Blackwell 特性：tcgen05、TMEM 与 2-SM MMA 在两级供给中的落点</h3>\n<p>tcgen05 是 Blackwell 的第五代 Tensor Core 指令族，其关键变化是把 MMA 的累加器从寄存器文件搬到 TMEM（Tensor Memory），使大 tile 的累加不再挤占通用寄存器。对 CodeMEM 的摘要节点重算，这意味着可以把多个摘要节点的小 GEMM 合并成一个更大的 tile：M 维由多个节点的 token 拼接，累加器驻留 TMEM，kernel 只需一次 launch 就覆盖整批摘要节点，直接压掉前述的 launch 开销。代价是 TMEM 容量有限，拼接的节点数受 tile 尺寸约束，超出则回退到多次 launch。对完整驻留节点的 attention，tcgen05 的价值在于 KV 读取与 MMA 的重叠——KV 从 HBM 流入的同时 MMA 在 TMEM 上累加，掩盖部分读延迟。</p>\n<p>2-SM MMA 让两个 SM 协作完成一个 MMA tile，累加器分布在两个 SM 的 TMEM 上。这适合完整驻留节点的大 batch attention：单节点 KV 长、batch 内节点数少时，2-SM 协作能把单个 tile 做大，提高 Tensor Core 利用率。但对摘要节点桶，节点多而每个极小，2-SM 协作的同步开销超过收益，应保持单 SM MMA。工程判断因此是按桶选 MMA 形态：完整节点桶走 2-SM 大 tile，摘要节点桶走单 SM 合并小 tile。混用会在批调度器里引入形态切换，增加打包约束——这正是 CodeMEM 批调度器“按节点驻留状态做变长序列打包”在算子层的真实含义：打包粒度不仅受 AST 拓扑序约束，还受 MMA 形态约束。</p>\n<p>显存代价在这里显式出现：TMEM 是独立于 HBM 与寄存器的存储层级，其容量决定单次 MMA 的最大 tile，进而决定摘要节点合并的上限。若 TMEM 被完整节点桶的大 tile 占满，摘要节点桶只能排队，两级供给在时间上串行化，prefill 延迟上升。可行的调度是把两级桶交错提交，让 TMEM 在完整节点的 KV 读取间隙被摘要节点的 GEMM 填充。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-18\">十八 · 编辑失效后的重算路径：精度与失效粒度的耦合</h3>\n<p>编辑落地后，系统按 AST 差异只失效受影响子树的 KV。失效子树的节点在下一轮变成摘要节点或重新完整驻留，其重算走的是摘要路径。这里精度选择与失效粒度耦合：失效子树越大，重算 token 越多，NVFP4 权重路径的算力收益越明显；失效子树小到十余 token 时，权重读取带宽而非算力是瓶颈，NVFP4 压缩权重读取的收益直接体现为延迟下降。反之，若失效跨多子树、重算量大，BF16 激活配 NVFP4 权重的组合开始受算力约束，此时应考虑把部分重算节点提升为完整驻留、复用未失效 KV，而非全部重算。</p>\n<p>一个具体判断：三处调用点节点的 KV 在编辑后保留，仅工具函数子树失效。第二轮用户追加“再补一个边界检查”，调用点节点因新引用分数上升被提升为完整驻留，预填序列重排并重新打包。重排意味着这些节点的 KV 从摘要态转为完整态，需要一次完整前向填充其 KV——这次前向的精度配置应与首次预填一致，否则同一节点在不同轮次的 KV 数值分布不一致，attention 复用会出现偏差。工程上应固定完整驻留节点的 KV 量化格式（如统一 FP8），升降级只改变驻留与否，不改变量化档位。代价是升降级时需做一次格式转换或重算，收益是跨轮 KV 复用的一致性。</p>\n<p>监控项应包含摘要重算 token 占比与失效子树规模，二者共同决定重算路径的算力压力。若摘要比例升高，重算成本侵蚀缓存收益，此时应下调摘要节点比例、把更多节点提升为完整驻留，用显存换算力；若失效子树规模扩大，重算量上升，应检查编辑是否跨多子树、是否可按更细的 AST 节点粒度失效。这两个调节方向相反，SLO 标定就是在二者之间找驻留比例的工作点。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-19\">十九 · 精度档位与硬件档位的标定</h3>\n<p>材料未给出量化方案，KV 驻留比例应随 NVFP4/FP8 精度选择调整，硬件档位与并行拓扑亦未给出，部署需按 B200/B300/GB200 NVL72 档位标定 KV 预算。这句话在算子层的含义是：精度档位决定单位显存能容纳的 KV token 数，进而决定 $B_{\\mathrm{KV}}$ 的取值，而 $B_{\\mathrm{KV}}$ 又反过来决定多少节点能进完整驻留集合。三者是一个闭环——降精度扩大预算、提升驻留比例、减少摘要重算，但降精度同时抬高数值误差风险。标定的顺序应是先定输出侧精度下限（代码 token 分布要求 BF16 累加），再定 KV 精度（FP8 为默认，NVFP4 仅在显存极度紧张时考虑），最后按剩余显存算 $B_{\\mathrm{KV}}$ 并调分数权重使驻留比例落在 SLO 工作点。</p>\n<p>GB200 NVL72 的机架级形态改变的是并行拓扑而非单卡精度选择：跨节点 KV 复用走 NVLink 5 与 NIXL 时，KV 以何种精度传输直接影响链路带宽占用。FP8 KV 跨节点传输的字节数是 BF16 的一半，在 NVL72 的 all-to-all 形态下这是实打实的带宽节省。但跨节点传输的 KV 若与本地 KV 精度不一致，接收端需转换，转换开销可能抵消带宽收益。工程判断是全网统一 KV 精度格式，把转换点收敛到写入侧一次完成。这一条与批调度器的变长打包共同构成 CodeMEM 在 Blackwell 档位上的部署约束：精度格式统一、打包粒度受 AST 拓扑与 MMA 形态双重约束、驻留比例按 SLO 在显存与算力之间滑动。</p>\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-20\">二十 · 显存账本的三个抽屉：权重、激活、KV</h3>\n<p>在 Blackwell 上做仓库级迭代推理，先把显存拆成三个互不挪用的抽屉。权重抽屉是静态的：B200 单卡 HBM3e 容量为 192 GB，B300 为 288 GB，GB200 NVL72 单 GPU 同样是 192 GB 量级但通过 NVLink 5 组成 72 卡域。权重占用按 <span class=\"formula\">$$M_w = P \\times b_w$$</span> 估算，P 为参数量，b_w 为每参数字节数；FP8 是 1 字节，NVFP4 是 0.5 字节外加每组缩放因子开销，因此同一模型从 FP8 换到 NVFP4，权重抽屉大致减半，省出来的容量正是 KV 抽屉的预算来源。激活抽屉在解码阶段很小，主要随批大小与中间张量宽度线性增长，真正随负载膨胀的是 KV 抽屉：<span class=\"formula\">$$M_{kv} = 2 \\times L \\times H_{kv} \\times d \\times b_{kv} \\times T \\times B$$</span>，其中 L 为层数、H_kv 为 KV 头数（GQA 下远小于注意力头数）、d 为头维、T 为序列长度、B 为并发序列数。CodeMEM 的切入点是把 T 从“整段提示长度”变成“完整驻留节点 token 加摘要节点 token”，于是 KV 抽屉的大小不再由仓库快照长度决定，而由预算约束 <span class=\"formula\">$$\\sum_{n\\in R} s(n)\\le B_{\\mathrm{KV}}$$</span> 下的驻留集合 R 决定。代价直接体现在批调度上：全量保留时 T 随轮次线性涨，B 被迫下调，吞吐塌陷；节点级预算把 T 压到可控区间，B 才能维持。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-21\">二十一 · 带宽瓶颈的位置：预填看算力，解码看 HBM</h3>\n<p>KV 账本算的是容量，但延迟由带宽决定。解码每生成一个 token，要把该序列全部 KV 从 HBM3e 读一遍，字节数为 <span class=\"formula\">$$2 \\times L \\times H_{kv} \\times d \\times b_{kv} \\times T$$</span>，与批大小无关；因此单序列解码的每 token 延迟近似为 <span class=\"formula\">$$t_{dec} \\approx \\frac{M_{kv}^{seq}}{BW_{\\mathrm{HBM}}}$$</span>。这意味着长上下文解码是纯带宽受限，算力大量闲置。批处理把多个序列的 KV 读取合并成一次大事务，摊薄了权重读取，但每序列的 KV 字节不变，所以吞吐上限由 <span class=\"formula\">$$\\text{Throughput} \\le \\frac{BW_{\\mathrm{HBM}} \\times \\eta}{M_{kv}^{seq}}$$</span> 封顶，η 为有效带宽利用率。CodeMEM 的两级供给在这里产生直接收益：摘要节点只保留少量 token，其 KV 读取量按比例缩小，等于把长尾节点的带宽税砍掉；完整驻留节点复用前缀缓存，预填阶段省掉重算，但解码阶段仍要读它的 KV——所以“摘要比例”本质是在容量、带宽与语义保真之间调一个旋钮。工程判断是：解码密集的低延迟补全场景应压低摘要比例以保语义，吞吐型批处理场景可抬高摘要比例换取更多并发序列。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-22\">二十二 · 分页、压缩、复用、卸载：四种手段的代价面</h3>\n<p>分页解决碎片：把 KV 切成固定大小 block，按需分配，变长序列打包时不再要求连续显存。CodeMEM 的批调度器按节点驻留状态做变长打包，若没有分页，节点升降级会导致驻留集合反复重排、显存碎片化，填充 token 比例上升。分页的代价是块表查询与跨块注意力的额外寻址，块越小碎片越少但元数据开销越大。压缩走两条路：一是 token 级摘要，即 CodeMEM 的摘要驻留，把低价值子树压成十余个 token 的摘要，重算时走轻量前向；二是数值级压缩，KV 以 FP8 存储，容量减半、带宽减半，代价是注意力分数精度损失，需与 NVFP4/FP8 的算子路径对齐。复用即前缀缓存：完整驻留节点命中缓存直接搬 KV，省掉预填算力；但 CodeMEM 明确指出前缀缓存命中率随编辑下降，因为 AST 结构一变，前缀的 token 序列就断。子树级增量失效正是为此设计——只失效受影响子树，未触及节点的缓存条目继续有效，把“整段重算”降为“局部重算”。卸载是把冷节点 KV 换出到主机内存或远端池，代价是 PCIe 或网络往返延迟，只适合跨轮间隔长、访问频度低的节点；在 NVL72 域内可用 NVLink 5 做 GPU 间 KV 迁移，带宽远高于 PCIe，但跨节点迁移仍要计入失效与重排开销。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-23\">二十三 · 一个可复算的显存预算</h3>\n<p>给一个只依赖公式、不依赖实验数字的算例。设模型 L=80 层、H_kv=8、d=128、KV 以 FP8 存（b_kv=1 字节），则每 token 每序列 KV 字节为 2×80×8×128×1 = 163,840 字节，约 160 KiB/token。若单序列驻留 32K token，KV 约 5.0 GiB；若并发 16 序列，KV 抽屉约 80 GiB。权重抽屉按 FP8 估算：若参数量落在百亿量级，权重为数十 GiB；换 NVFP4 后减半，腾出的容量可把并发序列数提高近一倍，或把单序列驻留长度翻倍。激活与工作区留出固定余量后，剩余容量即为 B_KV。此时把 CodeMEM 的预算约束代进去：完整驻留节点集合 R_full 的 token 总量乘以 160 KiB 不得超过 B_KV 减去摘要节点开销；摘要节点每节点十余 token，按节点数线性累加，占比小但重算前向不可忽略。这个算例的可复算性在于：只要给定 L、H_kv、d、b_kv、T、B 与权重精度，就能在 B200 的 192 GB 或 B300 的 288 GB 上直接算出 KV 抽屉占比，进而判断该档位下应把摘要比例设在什么区间。工程上应把“前缀缓存命中率、摘要重算 token 占比、失效子树规模、填充 token 比例”四项作为监控指标，因为它们分别对应复用收益、重算代价、失效代价与打包浪费，任何一项恶化都会让账本失衡。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-24\">二十四 · 失效粒度与预算竞争的耦合</h3>\n<p>CodeMEM 的节点可在摘要与完整驻留间升降级，预算竞争导致部分节点被淘汰，这与失效粒度耦合出一个容易被低估的代价。伪代码思路：编辑落地后计算 AST 差异，得到受影响子树集合 D；对 D 中每个节点标记 KV 失效并从驻留集合移除；对未受影响节点保留 KV 与分数；随后按新引用重算分数，按分数排序在 B_KV 内重新选择驻留集合，被挤出预算的节点降级为摘要并释放 KV。问题在于：一次编辑跨多个子树时，D 变大，失效范围扩大，重算量按 D 的 token 总量计；若仍按“单子树失效”估算延迟，会低估迭代轮次的实际开销。更隐蔽的是预算竞争的抖动——节点在完整与摘要之间反复升降级，每次升级都要重算并写回缓存，等于把缓存收益吃掉一部分。工程判断是给升降级加滞回：分数超过阈值才升级、低于另一阈值才降级，避免边界节点在两态间震荡；同时把失效集合按子树规模排序，优先重算小子树，用流水掩盖大子树的重算延迟。这一层的代价最终落在显存与带宽的联合账本上：失效越粗，重算算力越多；失效越细，元数据与调度开销越多；预算越紧，升降级越频繁。三者没有免费的解，只能按 SLO 标定。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-25\">二十五 · 按硬件档位标定驻留比例</h3>\n<p>材料明确 KV 预算按硬件档位配置，量化方案未给出，驻留比例应随 NVFP4/FP8 精度选择调整。落到 Blackwell 三档：B200 的 192 GB 适合中等并发、较长驻留的交互式补全，权重用 FP8 时 KV 抽屉相对宽裕，可压低摘要比例保语义；B300 的 288 GB 容量更大，可支撑更高并发或更长完整驻留集合，适合吞吐型批处理；GB200 NVL72 的 72 卡域把容量与带宽同时放大，跨卡 KV 复用与卸载有了 NVLink 5 的通道，但跨节点迁移的失效与重排开销必须计入，不能把“域内共享”当成零成本。一个具体例子：同一仓库修复请求在 B200 上以 FP8 权重、16 并发、32K 驻留运行，KV 抽屉接近 80 GiB，剩余容量留给激活与工作区后，摘要比例只能取较低值；换到 B300 上同样负载，多出的 96 GB 可把并发提到 24 或把驻留拉到 48K，此时可适度提高摘要比例以容纳更多会话。判断依据不是容量数字本身，而是“每 token KV 字节 × 驻留 token × 并发”与“HBM 带宽 ÷ 每序列 KV 字节”两条线是否同时满足延迟与吞吐 SLO；任何一条越界，就该调摘要比例或降并发，而不是靠加卡掩盖账本失衡。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-26\">二十六 · 驻留预算的边界：AST 记忆在显存账本上的失效条件</h3>\n<p>CodeMEM 的节点级驻留把 KV 显存从“按序列长度线性增长”改成“按语法价值排序分配”，但预算约束 <span class=\"formula\">$$\\sum_{n\\in R}s(n)\\le B_{\\mathrm{KV}}$$</span> 本身并不保证驻留集合稳定。分数是启发式加权，权重与衰减系数材料未给出，意味着同一仓库在不同硬件档位上会得到不同的驻留排序；更关键的是，分数每轮按新引用重算，节点在摘要与完整驻留之间升降级，预算竞争必然淘汰部分节点。淘汰掉的节点若在下一轮被重新引用，就要走重算路径，前缀缓存命中率随之下降。工程上必须把“驻留集合的抖动率”作为监控项：统计相邻两轮之间发生状态切换的节点数占驻留节点总数的比例，抖动率过高说明预算过紧或衰减系数过大，此时应上调 <span class=\"formula\">$$B_{\\mathrm{KV}}$$</span> 或降低引用频次的权重，而不是继续压缩摘要比例。</p>\n<p>摘要驻留是这套方案的第二条边界。摘要节点只保留少量 token 并在预填阶段重算，重算量随摘要节点数与摘要长度线性增长。设完整驻留节点集合为 <span class=\"formula\">$$F$$</span>、摘要节点集合为 <span class=\"formula\">$$S$$</span>，单轮预填的重算代价近似为 <span class=\"formula\">$$C_{\\mathrm{recalc}}\\approx |S|\\cdot \\bar{t}_{s}\\cdot c_{\\mathrm{fwd}}$$</span>，其中 <span class=\"formula\">$$\\bar{t}_{s}$$</span> 为平均摘要 token 数、<span class=\"formula\">$$c_{\\mathrm{fwd}}$$</span> 为单位 token 前向成本。摘要 token 太少会丢失定义—调用语义，解码阶段对摘要节点走轻量重算时可能补不回被截掉的类型信息与参数约束；摘要 token 太多则 <span class=\"formula\">$$C_{\\mathrm{recalc}}$$</span> 侵蚀缓存收益。这条曲线没有极值点可循，只能按 SLO 标定：低延迟补全场景应压低 <span class=\"formula\">$$|S|$$</span> 并把预算倾斜给高入度函数节点，中等吞吐批处理场景可放宽摘要比例以换取更多节点驻留。</p>\n<p>失效范围的估算是最容易出错的地方。系统按 AST 差异只失效受影响子树的 KV，单子树编辑时重算量可控；但一次跨文件重构往往同时触及函数体、调用点与导入边，失效子树在依赖图上连通，实际失效规模远大于单子树假设。若仍按“一次编辑等于一个子树”估算迭代延迟，会系统性低估重算量。可复算的粗算方式是：以失效子树覆盖的节点数为 <span class=\"formula\">$$N_{\\mathrm{inv}}$$</span>、其中完整驻留节点占比为 <span class=\"formula\">$$\\rho$$</span>，则单轮额外重算的 KV 条目量约为 <span class=\"formula\">$$N_{\\mathrm{inv}}\\cdot(1-\\rho)$$</span> 个节点的摘要重算加上 <span class=\"formula\">$$N_{\\mathrm{inv}}\\cdot\\rho$$</span> 个节点的整段重算。工程判断是：当 <span class=\"formula\">$$\\rho$$</span> 高而失效子树大时，增量失效的收益被重算抵消，此时应临时冻结跨子树编辑的驻留升级，等编辑落地后再统一重排预填序列。</p>\n<p>还有两项前置代价不在 KV 账本里却直接压 SLO。AST 解析与依赖图构建是每请求前置步骤，超大仓库下预处理延迟材料未给出，低延迟补全场景可能被这一步拖垮；批调度器按节点驻留状态做变长序列打包，打包粒度受 AST 拓扑序约束，拓扑序靠前的节点必须先拼，填充 token 比例因此高于按长度排序的常规打包。下表给出一个可复算的预算骨架，数值需按 B200／B300／GB200 NVL72 档位与 NVFP4／FP8 精度选择自行标定，表中只列结构不列实测值。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>构成</th><th>可调旋钮</th><th>失效信号</th></tr></thead><tbody><tr><td>权重驻留</td><td>模型权重按精度档位占用</td><td>NVFP4／FP8 选择</td><td>精度切换后预算重算</td></tr><tr><td>完整节点 KV</td><td><span class=\"formula\">$$|F|\\cdot \\bar{t}_{f}$$</span></td><td>驻留比例、<span class=\"formula\">$$B_{\\mathrm{KV}}$$</span></td><td>抖动率上升</td></tr><tr><td>摘要节点 KV</td><td><span class=\"formula\">$$|S|\\cdot \\bar{t}_{s}$$</span></td><td>摘要 token 数</td><td>重算占比升高</td></tr><tr><td>失效重算余量</td><td><span class=\"formula\">$$N_{\\mathrm{inv}}\\cdot(1-\\rho)$$</span></td><td>失效粒度、冻结策略</td><td>跨子树编辑频次</td></tr></tbody></table>\n<p>这张表的用法是把 <span class=\"formula\">$$B_{\\mathrm{KV}}$$</span> 拆成四项后逐项监控：完整节点 KV 与摘要节点 KV 之和不得超过预算，失效重算余量必须留出跨子树编辑的峰值，权重驻留随精度档位变化时其余三项要同步重算。任何一项逼近上限，都意味着驻留策略已进入失效区，此时继续压缩摘要 token 只会把成本推到解码阶段的重算上，而不是真正省下显存。</p>\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-27\">二十七 · 连续批处理在 AST 驻留状态上的重定义</h3>\n<p>常规连续批处理把“序列”当作不可分割的调度单位：一个请求进批，它的全部 KV 一起进显存，一起被迭代步推进。CodeMEM 的记忆管理层把这一假设拆开了——同一个请求内部的上下文被切成完整驻留节点与摘要节点两类，二者的 KV 生命周期完全不同。完整节点命中前缀缓存后直接复用，摘要节点每轮都要重算十余 token 并写回缓存。于是批调度器面对的输入不再是“N 条等长序列”，而是“N 个请求 × 若干驻留片段”，每个片段有自己的长度、驻留状态与失效时刻。</p>\n<p>调度器的核心动作因此变成变长序列打包：按节点驻留状态把同一请求的片段拼成一条预填序列，片段之间不插入填充 token，而是用 AST 拓扑序（定义在前、调用在后）决定拼接顺序。填充浪费的来源从“批内最长序列对齐”转移到“拓扑序约束下的空洞”——若某调用点节点被提升为完整驻留，它必须排在定义节点之后，中间可能留下无法被其他请求片段填补的间隙。设批内片段集合为 $P$，片段长度为 $l_p$，打包后的有效 token 占比可写成：</p>\n<div class=\"formula\">$$\\eta_{\\text{pack}}=\\frac{\\sum_{p\\in P} l_p}{\\max_{b\\in \\text{batch}} L_b\\cdot |P|}$$</div>\n<p>工程代价直接落在显存与吞吐上：$\\eta_{\\text{pack}}$ 下降意味着同样的 KV 预算装更少的有效上下文，批大小被迫收缩，解码阶段的 token 吞吐随之下降。一个具体例子是首轮修复请求——工具函数节点入度为三、跨文件引用两次，分数最高，分配完整 KV；其上游导入节点仅保留摘要。打包时函数节点片段在前、导入摘要片段在后，中间没有其他请求的片段可插入，形成一段拓扑序空洞。调度器此时的选择是把这个空洞留给同会话下一轮迭代的调用点节点，而不是塞入无关请求，避免跨会话污染 AST 记忆状态。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-28\">二十八 · Chunked prefill 与两级上下文供给的耦合</h3>\n<p>Chunked prefill 的原始动机是把长预填切成小块，与解码步交错执行以压平尾延迟。CodeMEM 的预填序列天然就是分块的：完整节点块走缓存查表，摘要节点块走轻量重算。这带来一个调度上的耦合——重算块的算力需求与复用块的显存带宽需求在同一迭代步内竞争 SM 与 HBM。若把重算块与复用块混在同一 chunk 内，SM 在等待缓存查表结果时处于空转；若分开成两个 chunk，则解码步被插入两次，首 token 时延（TTFT）增加一个 chunk 的调度开销。</p>\n<p>可操作的伪代码思路是按块类型排序后再切 chunk：先发所有复用块（低算力、高带宽），再发所有重算块（高算力、低带宽），使每个 chunk 内部的资源画像一致。设复用块总 token 数为 $T_r$、重算块总 token 数为 $T_c$，chunk 大小为 $C$，则预填阶段被切成的 chunk 数为：</p>\n<div class=\"formula\">$$N_{\\text{chunk}}=\\left\\lceil \\frac{T_r}{C}\\right\\rceil+\\left\\lceil \\frac{T_c}{C}\\right\\rceil$$</div>\n<p>代价是 TTFT 随 $N_{\\text{chunk}}$ 线性增长，而解码吞吐因资源画像对齐而改善。具体例子：第二轮用户追加“再补一个边界检查”，三处调用点节点因新引用分数上升被提升为完整驻留，预填序列重排——原本的摘要块被替换为复用块，$T_c$ 下降、$T_r$ 上升，chunk 数减少，TTFT 反而比首轮更低。这是 AST 驱动的驻留升降级对 chunked prefill 的正向反馈：分数更新不只是省显存，还改变了预填的资源画像分布。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-29\">二十九 · 优先级、抢占与摘要节点的降级路径</h3>\n<p>多会话并行迭代时，每个会话维护独立的 AST 记忆状态与 KV 驻留集合，KV 预算在会话间是竞争关系。CodeMEM 的价值分数 $s(n)=\\alpha\\,\\mathrm{indeg}(n)+\\beta\\,\\mathrm{ref}(n)+\\gamma\\,e^{-\\delta\\,\\mathrm{dist}(n)}$ 天然提供了一个跨会话的优先级排序依据：分数高的节点优先获得完整驻留，分数低的节点被降级为摘要或淘汰。调度器据此实现抢占——当新请求的完整驻留需求超出剩余预算时，从当前驻留集合中挑出分数最低的节点降级，释放其 KV 给新请求。</p>\n<p>抢占的代价不对称：降级一个完整节点只需丢弃其 KV，下一轮重算摘要 token；但升级一个摘要节点需要重算并写回缓存，且重算发生在关键路径上。因此调度器应偏向“降级易、升级贵”的策略，把预算留给分数稳定上升的节点。失败模式在此显形：若把 AST 节点分数当作静态优先级，忽略编辑后引用变化导致的驻留升降级，会造成缓存命中率下降——被错误降级的节点在下一轮被迫重算，重算 token 占比上升，侵蚀缓存收益。具体例子：跨多子树编辑时失效范围扩大，若仍按单子树假设估算重算量，调度器会低估实际延迟，把预算错配给即将失效的子树。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-30\">三十 · 分离式预填/解码与子树失效的边界</h3>\n<p>分离式预填/解码把预填与解码放到不同 GPU 池，预填池产出 KV 后经 NVLink 5 或 NIXL 传给解码池。CodeMEM 的子树级失效在这里获得一个新的边界问题：失效发生在解码池产出补丁、编辑落地之后，而失效的 KV 条目可能同时存在于预填池的缓存与解码池的驻留集合中。若只在解码池失效，预填池的前缀缓存仍持有过期 KV，下一轮预填会命中脏条目；若两池同步失效，跨池通信开销随失效子树规模增长。</p>\n<p>工程判断是把失效粒度与传输粒度对齐：AST 差异给出的受影响子树若小于一次 KV 传输的块大小，则合并为一次整块失效，避免为十几个 token 的子树发起一次跨池同步。设失效子树 token 数为 $T_f$、传输块大小为 $B_t$，实际同步的块数为 $\\lceil T_f/B_t\\rceil$，跨池失效的通信代价正比于该块数而非 $T_f$。具体例子：首轮编辑只触及工具函数体，失效该子树 KV，三处调用点节点 KV 保留——调用点节点在解码池继续驻留，预填池只需失效函数体对应的块，跨池同步量被压到单块级别。第二轮调用点节点升级为完整驻留时，预填池重算并推送新 KV，此时传输量上升但换来了后续轮次的缓存命中。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-31\">三十一 · 尾延迟的压缩点与 SLO 标定</h3>\n<p>尾延迟在仓库级迭代生成里主要由三件事驱动：AST 解析与依赖图构建的前置延迟、摘要节点重算的额外前向、以及跨多子树编辑时的失效范围扩大。三者中只有第二项能被批调度直接摊薄——重算块可以与复用块交错，把重算的算力峰值藏进解码步的空隙；第一项是请求前置步骤，超大仓库下预处理延迟未给出，无法靠批处理隐藏，只能靠会话级缓存 AST 图跨轮复用；第三项取决于编辑形态，调度器能做的是按 AST 差异预估失效规模，提前把预算从即将失效的子树转移到稳定节点。</p>\n<p>监控项应含前缀缓存命中率、摘要重算 token 占比与失效子树规模，这三者共同决定尾延迟的分布形状。命中率下降意味着更多节点走重算路径，重算 token 占比上升直接推高 TTFT；失效子树规模扩大则意味着跨池同步块数增加，P99 延迟被少数大失效事件拉长。SLO 标定的可操作变量是驻留比例——在 Blackwell 档位上按 NVFP4/FP8 精度选择调整 KV 预算后，驻留比例越高，命中率越高但预算竞争越激烈，降级与抢占事件越频繁。具体例子：低延迟补全 SLO 下应压低摘要比例、提高完整驻留比例，把重算路径留给少数低分数节点；中等吞吐批处理 SLO 下则可放宽摘要比例，用重算换取更大的批大小与更高的 $\\eta_{\\text{pack}}$。这一取舍的落点是批调度器按驻留状态打包变长序列时的填充 token 比例与显存碎片监控——填充比例上升说明拓扑序空洞在扩大，碎片上升说明降级与升级的抖动过于频繁，两者都是驻留比例需要回调的信号。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-32\">三十二 · 节点驻留状态驱动的变长打包：调度边界与失效代价</h3>\n<p>CodeMEM 的批调度器与传统连续批处理（continuous batching）的差异在于打包粒度不是请求而是 AST 节点驻留状态。每个请求的预填序列由两类片段拼成：完整驻留节点直接查前缀缓存复用 KV，摘要节点需重算少量 token 并写回缓存。调度器按节点拓扑序把这两类片段交错打包成变长序列，填充 token 比例取决于拓扑序约束——同一函数体内的语句节点必须连续，跨文件调用边又要求被调节点先于调用点出现，这使打包自由度低于纯 token 级连续批处理。代价体现在显存碎片：节点级驻留集合随轮次升降级，KV 页的分配与回收频率高于请求级批处理，Blackwell 档位上需按 B200／B300／GB200 NVL72 的 KV 预算标定驻留比例，否则碎片会侵蚀有效批大小。一个具体例子：某工具函数节点入度为三、跨文件引用两次，分数最高获完整驻留；其上游导入节点仅保留摘要 token，预填时前者命中缓存、后者重算十余 token，两者在同一批次内被拼进不同序列位置，调度器必须等摘要重算完成才能释放该批的填充槽位。</p>\n<p>时延与吞吐的取舍落在摘要比例这一旋钮上。设一轮迭代中完整驻留节点集合为 $R_f$、摘要节点集合为 $R_s$，预填总代价可写成：</p>\n<div class=\"formula\">$$T_{\\mathrm{prefill}} \\approx \\sum_{n\\in R_f} T_{\\mathrm{cache}}(n) + \\sum_{n\\in R_s} T_{\\mathrm{recalc}}(n) + T_{\\mathrm{pack}},\\quad |R_s|/|R_f| \\uparrow \\Rightarrow T_{\\mathrm{prefill}}\\uparrow,\\ \\text{批吞吐}\\downarrow$$</div>\n<p>提高摘要比例能压低 KV 驻留显存、容纳更大批，但重算前向随摘要 token 数线性增长，且重算结果写回缓存又占用带宽。材料未量化该权衡，工程上只能按 SLO 标定：低延迟补全场景应压低摘要比例、优先完整驻留；中等吞吐批处理可放宽摘要比例换取批大小。尾延迟的主要来源不是单请求重算，而是跨多子树编辑时的失效范围扩大——若仍按单子树假设估算重算量，会低估迭代轮次的实际延迟。编辑只触及某函数体时系统按 AST 差异失效该子树 KV、三处调用点节点保留，这是理想路径；一旦编辑横跨多个文件，失效子树规模叠加，预填重算量随之跳升，尾延迟出现长尾。</p>\n<p>优先级与抢占在节点级驻留上表现为升降级而非请求级驱逐。分数更新在每轮迭代后按新引用重算，节点可在摘要与完整驻留间双向迁移，预算竞争导致低分节点被淘汰。把分数当静态优先级是典型失效条件：编辑后引用变化未触发升降级，缓存命中率下降而调度器仍按旧驻留集合打包。分离式预填/解码在此方案中并非天然契合——摘要节点的轻量重算发生在预填侧，解码侧对完整节点直接复用 KV，两侧的驻留集合必须一致，否则跨节点迁移会引入额外同步。工程判断是：AST 解析与依赖图构建作为请求前置步骤，超大仓库下预处理延迟未给出，可能直接冲击低延迟补全 SLO，部署时应把解析开销纳入首 token 时延预算，并对跨多子树编辑预留失效放大的重算余量。</p>\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-33\">三十三 · 并行拓扑：CodeMEM 的 AST 记忆状态放在哪张卡上</h3>\n<p>CodeMEM 的记忆单元是 AST 四级节点，每个节点带价值分数与 KV 驻留状态。这套状态在并行推理里不是免费的：它必须与切分后的模型权重、KV 分片、前缀缓存索引对齐。张量并行（TP）把单层权重按列/行切到多卡，每层做一次 All-Reduce 合并部分和；流水并行（PP）按层切段，段间只传激活，代价是微批气泡；专家并行（EP）把 MoE 专家分散，路由结果触发 All-to-All；数据并行（DP）复制权重、分摊请求，梯度不参与推理，但每张卡都要各自维护一份 AST 记忆状态与 KV 驻留集合。对 CodeMEM 而言，关键判断是：节点级驻留决策必须在“会话所属的那组卡”上保持一致，否则同一节点在不同 DP 副本里被降级为摘要、在另一副本里保留完整 KV，前缀缓存命中率与重算量都会分叉。</p>\n<p>一个具体机制：把 AST 依赖图按子树做亲和性划分，同一函数节点的完整 KV 与其调用点节点尽量落在同一 TP 组内，减少跨组查缓存的往返。代价是负载不均——入度高的工具函数节点会集中到少数卡上，KV 显存占用倾斜。工程上以“每卡驻留节点数上限”做二次约束，把超额节点降级为摘要驻留，这正好复用价值分数排序：</p>\n<div class=\"formula\">$$\\text{cap}_g=\\left\\lfloor \\frac{B_{\\mathrm{KV}}}{N_{\\mathrm{TP}}\\cdot N_{\\mathrm{PP}}}\\right\\rfloor,\\quad \\sum_{n\\in g}s(n)\\le \\text{cap}_g$$</div>\n<p>例子：一次修复请求触及某工具函数与三处调用点，若该函数节点与调用点被分到不同 PP 段，预填时调用点需要等待上游段激活才能拼接上下文，段间气泡被 AST 拓扑序放大。把同子树的节点约束到同段，能把气泡压到段内，但会牺牲 PP 各段的负载均衡。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-34\">三十四 · NVLink 5 与 NVSwitch：域内带宽决定 All-Reduce 是否可见</h3>\n<p>Blackwell 档位上，NVLink 5 与 NVSwitch 构成机架内全连接域，GB200/GB300 NVL72 把 72 个 GPU 放在同一 NVLink 域内。TP 的 All-Reduce 每层都要跑，通信量与隐藏维度、批内 token 数成正比；在 NVLink 域内它通常被计算掩盖，一旦跨域走 InfiniBand，All-Reduce 就从“背景噪声”变成关键路径。CodeMEM 的预填序列是变长打包的，批内 token 数随驻留状态波动，All-Reduce 的参与量也随之波动，这让 TP 组的通信预算难以按固定批大小估算。</p>\n<p>公式侧写：单层 All-Reduce 的传输量为 $2\\cdot\\frac{T-1}{T}\\cdot B\\cdot H$（B 为批内 token 数，H 为隐藏维，T 为 TP 度），环形实现的时延近似为 $\\frac{2(T-1)}{T}\\cdot\\frac{S}{W}$（S 为消息字节，W 为链路带宽）。当 B 因变长打包而下降时，通信时延占比上升，TP 度越大越明显。代价落在解码阶段：解码每步只处理少量 token，All-Reduce 的固定时延无法被计算掩盖，TP 度超过一定值后单步延迟反而变差。工程判断是预填用高 TP 度吃带宽、解码用低 TP 度或 DP 分摊请求，CodeMEM 的批调度器按驻留状态打包时正好可以把预填与解码的并行度分开配置。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-35\">三十五 · All-to-All 与 EP：MoE 路由与 AST 子树亲和性的冲突</h3>\n<p>EP 下每个 token 的路由结果决定它去哪些专家，All-to-All 交换 token 与专家输出。CodeMEM 的上下文由完整驻留节点与摘要节点混合拼接，摘要节点重算产生的 token 与完整节点复用的 KV 在同一个批里，路由分布因此不均匀：定义—调用链上的 token 集中命中少数专家，导入节点摘要 token 分散。All-to-All 的负载不均直接转化为尾延迟，因为最慢的那条链路决定整批完成时间。</p>\n<p>一个可操作的机制：在预填拼接阶段按 AST 节点分组，把同一子树的 token 连续排布，使路由结果在局部聚集，减少 All-to-All 的乱序度；代价是变长打包的填充 token 比例上升，与批调度器“减少填充浪费”的目标直接冲突。这是一个显式的权衡，需要按 SLO 标定分组粒度。例子：某函数节点完整驻留、其上游导入节点仅摘要，若把两者 token 交错排布，All-to-All 后专家负载方差变大；按子树分段排布后方差下降，但段间填充增加。监控项应包含 All-to-All 尾延迟与填充 token 比例两条曲线，二者此消彼长。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-36\">三十六 · NIXL 传输：跨节点 KV 搬运与子树失效的粒度匹配</h3>\n<p>NIXL 面向推理场景的点对点 KV/状态传输，把 KV 块从预填节点搬到解码节点、或在分离式部署中跨节点复用前缀缓存。CodeMEM 的子树级失效在这里有直接价值：编辑只触及某函数体时，只需让该子树对应的 KV 块失效，其余节点的 KV 块继续在远端驻留，无需整段前缀重传。传输粒度必须与 AST 节点对齐——若 NIXL 按固定大小块搬运，而子树边界与块边界不重合，失效会退化为整块重传，增量失效的收益被吃掉。</p>\n<p>代价侧：跨节点 KV 搬运的字节数与驻留比例成正比，完整驻留节点越多，NIXL 传输量越大；摘要节点重算则把成本从带宽换到算力。公式化地看，单轮迭代的跨节点搬运量近似为 $\\sum_{n\\in R_{\\text{full}}} \\text{bytes}(n)\\cdot \\mathbb{1}[\\text{invalid}(n)]$，失效集合越小搬运越少。例子：三处调用点节点在编辑后未失效，若它们驻留在远端解码节点，本轮只需搬运被编辑函数子树的 KV；若按整段前缀处理，则要把整个上下文重传一遍。工程上应把 NIXL 的注册粒度做成 AST 节点级，并让失效标记随编辑事件同步下发。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-37\">三十七 · 通信何时成为瓶颈：三个可判定的信号</h3>\n<p>不要用“通信占比高”这种模糊判断。可判定的信号有三个。其一，预填阶段 All-Reduce 时延与单层计算时延的比值随批内 token 数下降而上升——CodeMEM 的变长打包让批内 token 数天然偏低，TP 度越高越早触顶。其二，All-to-All 尾延迟与平均延迟的比值扩大，说明 EP 路由被 AST 子树分组破坏，专家负载方差上升。其三，NIXL 传输字节数占单轮迭代总字节的比例随失效子树规模增长，跨多子树编辑时失效范围扩大，若仍按单子树假设估算重算量，会低估实际延迟。</p>\n<p>对应的工程动作：预填与解码分离并行度配置；按子树分组排布 token 并监控填充比例；把 NIXL 注册粒度与 AST 节点对齐。表格给出判定与动作的对应：</p>\n<table class=\"mini\"><thead><tr><th>信号</th><th>观测位置</th><th>工程动作</th></tr></thead><tbody><tr><td>All-Reduce 时延/计算时延上升</td><td>预填段，批内 token 数下降</td><td>预填提高 TP 度，解码降 TP 或转 DP</td></tr><tr><td>All-to-All 尾延迟/均值扩大</td><td>EP 路由后</td><td>按 AST 子树分组排布，接受填充上升</td></tr><tr><td>NIXL 字节占比上升</td><td>跨节点 KV 搬运</td><td>节点级注册粒度，子树失效标记同步</td></tr></tbody></table>\n<p>例子：某会话第二轮追加“再补一个边界检查”，调用点节点因新引用分数上升被提升为完整驻留，预填序列重排并重新打包。若此时 TP 组按旧批大小估算通信预算，All-Reduce 时延会被低估；正确做法是按新驻留集合重算批内 token 数，再决定是否临时降 TP 度。这一判断落在具体机制上：驻留状态变化即通信预算变化，批调度器与并行配置必须联动，而不是各自独立调参。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-38\">三十八 · 并行切分下节点驻留的通信代价与失效边界</h3>\n\n<p>CodeMEM 的节点级 KV 驻留一旦落到 TP/EP/PP/DP 切分上，就不再是单卡内的预算分配问题。完整驻留节点的 KV 按张量并行切到各 rank，摘要节点重算时各 rank 需各自前向一小段 token 再聚合；当某节点因编辑被失效、下一轮又被提升为完整驻留时，它的 KV 必须重新在 TP 组内按头维切分写入，这一步是集合通信而非本地拷贝。若节点跨 PP 阶段（例如函数定义在浅层、调用点在深层），失效信号还要沿流水线逐 stage 传播，stage 间只能靠点对点发送摘要 token 或重算指令。EP 场景更尖锐：MoE 解码时 token 要 All-to-All 分发到专家所在 rank，而 CodeMEM 的变长打包让每个 rank 的 token 数随驻留状态抖动，All-to-All 的负载不均直接转化为等待。NVLink 5 与 NVSwitch 提供的是机柜内高带宽域，GB200 NVL72 把这一域扩到整柜，但跨柜、跨节点仍要落到 NIXL 之类的传输层，此时一次节点 KV 迁移的代价足以抵消前缀缓存带来的收益。判断标准很直接：设单轮失效子树规模为 $F$、重算 token 数为 $T_r$、迁移字节数为 $M$，则增量失效的净收益为\n\n<div class=\"formula\">$$\\Delta = \\underbrace{c_{\\mathrm{recalc}}\\,T_r}_{\\text{省下的整段重算}} - \\underbrace{\\left(c_{\\mathrm{comm}}\\,M + c_{\\mathrm{parse}}\\,F\\right)}_{\\text{通信与解析新增}}$$</div>\n\n只有当 $\\Delta&gt;0$ 时，子树级失效才在并行拓扑下成立；$M$ 随 TP 度与 PP 阶段数放大，$F$ 随编辑跨子树程度放大，两者共同决定这条路径的失效边界。</p>\n\n<p>通信成为瓶颈的触发条件可以按拓扑分档看清。TP 组内 All-Reduce 发生在每次摘要节点重算后的激活聚合，其代价随 TP 度近似线性上升而单卡计算量下降，于是摘要比例越高、TP 度越大，重算路径越被通信支配——这正是摘要 token 数量不能一味压小的原因：token 太少虽降低重算 FLOPs，却让 All-Reduce 的固定延迟占比更高。PP 阶段的瓶颈在气泡：节点升降级导致某 stage 的预填序列长度突变，流水线需要重新填排，填充浪费与 stage 间等待叠加。DP 副本间的瓶颈则是状态同步：每个会话维护独立 AST 记忆状态，副本间不共享 KV，但负载均衡器按会话路由时，热点仓库的解析与打分集中到少数副本，形成计算倾斜。EP 的 All-to-All 最敏感于打包粒度，而 CodeMEM 的打包受 AST 拓扑序约束，同一子树的节点倾向连续排列，这在变长序列打包上是好事，在专家分发上却可能造成 token 集中涌向少数专家。工程上应把监控项钉在三个量上：前缀缓存命中率、摘要重算 token 占比、失效子树规模，任一恶化都意味着通信项在 $\\Delta$ 中开始占主导。</p>\n\n<table class=\"mini\"><thead><tr><th>切分维度</th><th>CodeMEM 触发的集合通信</th><th>瓶颈形态</th><th>缓解手段</th></tr></thead><tbody><tr><td>TP</td><td>摘要重算后的激活 All-Reduce、KV 按头维重切</td><td>摘要比例高时通信支配重算</td><td>按 SLO 抬高摘要 token 下限，减少重算次数</td></tr><tr><td>PP</td><td>stage 间摘要 token 与失效指令点对点</td><td>节点升降级引起流水线气泡</td><td>按驻留状态预排 stage 序列，限制单轮升降级节点数</td></tr><tr><td>EP</td><td>解码 token 的 All-to-All 专家分发</td><td>拓扑序打包导致专家负载倾斜</td><td>打包时对专家维度做二次均衡</td></tr><tr><td>DP</td><td>无 KV 共享，仅会话路由与状态同步</td><td>热点仓库副本计算倾斜</td><td>按仓库哈希与会话亲和性路由</td></tr></tbody></table>\n\n<p>失效条件里最容易被低估的是跨多子树编辑。CodeMEM 的增量失效按 AST 差异只失效受影响子树，这一假设在单函数补丁上成立；但一次重构式修改（改接口签名并同步三处以上调用点）会让失效集合从一棵子树扩散到定义—调用链上的多个节点，此时 $F$ 骤增，解析与依赖图重建的前置开销也同步上升，而前缀缓存命中率因 AST 结构变化频繁失效而下降。若部署仍按单子树假设估算重算量，就会系统性低估迭代轮次的实际延迟，低延迟补全 SLO 首先被击穿。另一个失效条件是分数更新滞后：节点价值分数在每轮迭代后按新引用重算，若把分数当静态优先级、忽略编辑后引用变化导致的驻留升降级，被淘汰的节点在下一轮又要重新预填，缓存命中率随之跌落。预算竞争还会带来淘汰抖动——两个分数接近的节点在预算边界反复升降级，每次升降都触发一次 KV 重切与打包重排，这种抖动在 TP 度大、NVLink 域内尚可吸收，一旦跨 NIXL 传输就变成实打实的延迟。</p>\n\n<p>落到 Blackwell 档位的工程判断是：把 KV 预算按硬件档位配置，同时把驻留比例与摘要比例作为一对联动参数标定，而不是各自独立调。NVFP4/FP8 精度选择改变的是单节点 KV 的字节数，从而改变同一预算下能容纳的完整驻留节点数，进而改变 TP 组内重切的频率；精度越低，预算内可驻留节点越多，失效时需迁移的字节数 $M$ 反而可能上升，$\\Delta$ 的符号需要重新核算。在 GB200 NVL72 整柜域内，All-to-All 与 All-Reduce 的带宽足以让多数仓库级会话把通信压在计算之下，此时瓶颈回到 AST 解析的前置延迟；而跨柜部署时，NIXL 传输的每一次节点 KV 迁移都应被视为高代价操作，应优先保证失效集合局部化、限制单轮升降级节点数，并让批调度器在打包时同时满足 AST 拓扑序与专家/阶段负载均衡两个约束。CodeMEM 的通信边界不在带宽数字上，而在失效粒度与切分维度的匹配度上：失效集合越局部、切分越同构，$\\Delta$ 越稳；一旦编辑跨子树、切分跨域，结构感知的预算分配就必须让位于保守的整段重算。</p>\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-39\">三十九 · 精度塌陷：从“分数排序”到“预算挤兑”的静默失效</h3>\n<p>CodeMEM 的驻留决策本质是一次带预算约束的排序：<div class=\"formula\">$$s(n)=\\alpha\\,\\mathrm{indeg}(n)+\\beta\\,\\mathrm{ref}(n)+\\gamma\\,e^{-\\delta\\,\\mathrm{dist}(n)},\\quad \\sum_{n\\in R}s(n)\\le B_{\\mathrm{KV}}$$</div>预算满时，低分节点被降级为摘要驻留，甚至被淘汰出驻留集合。工程上最危险的失败模式不是崩溃，而是<b>精度塌陷的静默发生</b>：被淘汰的节点恰好是某条定义—调用链的中间环节，摘要 token 不足以承载其语义，模型仍能生成语法合法的补丁，却在跨文件符号解析上系统性出错。这类错误不会触发任何异常，监控里只表现为“通过率缓慢下滑”，而前缀缓存命中率反而上升——因为被淘汰的节点不再重算，指标看起来更“健康”。</p>\n<p>诊断这类问题需要把<b>驻留结构</b>而非仅命中率纳入监控。具体机制是：对每个被降级或淘汰的节点，记录其 <code>indeg</code> 与 <code>ref</code> 的当前值，并统计“降级节点中入度≥2 的比例”。若该比例随轮次上升，说明预算竞争正在挤掉结构关键节点，而非挤掉噪声节点。推理系统代价上，这直接体现为补丁返工率与人工复核成本上升，而不是显存或延迟指标恶化——因此必须建立从“生成结果质量”到“驻留状态”的回溯链路，例如按会话记录每轮被淘汰节点集合，与最终补丁的编译/测试失败位置做关联。一个具体例子：某工具函数入度为三，首轮完整驻留；第二轮新增边界检查后，三处调用点 <code>ref</code> 上升，若预算未同步扩容，原本驻留的上游导入节点被挤出，模型在补丁中漏改一处调用点。此时命中率指标无异常，但依赖链已断。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-40\">四十 · OOM 与批抖动：变长打包的两种崩溃形态</h3>\n<p>批调度器按节点驻留状态做变长序列打包，这一设计把显存压力从“序列长度”转移到“驻留集合的拓扑分布”。OOM 的典型诱因不是单条请求过长，而是<b>多会话并发下驻留集合的叠加</b>：每个会话维护独立的 AST 记忆状态与 KV 驻留集合，若多个会话同时把高入度子树提升为完整驻留，累计 KV 会突破 <code>B_KV</code> 的物理上限。由于预算约束是<b>按会话</b>而非全局施加的，调度器在打包时看到的只是局部可行，全局不可行。</p>\n<p>批抖动则是另一形态：节点在摘要与完整驻留间升降级，导致预填序列长度在相邻批次间跳变。打包粒度受 AST 拓扑序约束，重排后填充 token 比例骤升，吞吐出现锯齿。定位方法是监控两个量：<b>批内序列长度方差</b>与<b>填充 token 占比</b>。前者突增说明驻留状态在批次间不稳定，后者突增说明拓扑序约束与变长打包冲突。工程判断上，应把驻留升降级做成<b>批次边界上的批量操作</b>，而非解码中途即时生效——代价是首轮延迟略增，收益是批形状稳定。具体例子：三处调用点在同一轮被提升，若逐节点即时重排，同一批次内会出现三次序列重打包；若延迟到批次结束统一重排，填充浪费只发生一次。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-41\">四十一 · 尾延迟：AST 预处理与摘要重算的叠加</h3>\n<p>尾延迟的根源在请求前置路径上：AST 解析与依赖图构建是<b>同步前置步骤</b>，超大仓库下其耗时未在材料中量化，但它与摘要节点重算串联在同一条关键路径上。摘要节点重算引入额外前向，摘要比例升高时重算成本侵蚀缓存收益——这意味着尾延迟与精度塌陷存在<b>反向耦合</b>：为保精度而提高摘要比例，尾延迟恶化；为压尾延迟而降低摘要比例，依赖链丢失。</p>\n<p>定位手段是把预填阶段拆成三段计时：解析耗时、完整节点缓存查找耗时、摘要节点重算耗时。若解析段占比随仓库规模线性上升，说明预处理是尾延迟主因，应考虑把依赖图构建做成增量式——编辑只触及单子树时，复用上一轮的图结构，仅对受影响子树重解析。伪代码思路：<code>if diff.subtrees == 1: graph = graph.patch(subtree) else: graph = parse(repo)</code>。推理系统代价上，增量解析把 P99 预填延迟从“随仓库规模增长”变为“随编辑范围增长”，但需要维护图版本与失效标记，增加内存开销。具体例子：单函数体编辑只触发该子树重解析，三处调用点节点沿用旧图与旧 KV，尾延迟不再受仓库总规模支配。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-42\">四十二 · 静默降级：分数更新滞后与缓存假命中</h3>\n<p>分数在每轮迭代后按新引用重算，但<b>重算发生在解码之后</b>，而预填序列在解码前已按旧分数拼接。这形成一个时间窗：本轮编辑产生的新引用尚未反映到驻留决策中，下一轮预填仍按旧排序执行。若新引用恰好指向一个已被降级的节点，系统会走摘要重算路径，产出语义不完整的上下文，而前缀缓存报告“命中”——因为摘要节点本身也在缓存中。这是<b>缓存假命中</b>：命中率指标上升，但命中的是低价值摘要而非完整 KV。</p>\n<p>诊断需要区分两类命中：完整驻留命中与摘要命中，并分别统计其对应的下游补丁质量。监控项应含“摘要重算 token 占比”与“摘要命中后补丁的跨文件修改完整率”。工程上可引入<b>预判升降级</b>：在解码阶段检测到新引用写入时，立即标记目标节点为“待提升”，下一轮预填优先按标记排序，而非等待轮末全量重算。代价是标记逻辑增加解码路径分支，收益是消除一轮的假命中窗口。具体例子：第二轮用户追加边界检查，调用点节点 <code>ref</code> 上升；若等到轮末才重算，第三轮预填仍可能用摘要供给，补丁漏改；预判标记则让第三轮直接完整驻留。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-43\">四十三 · 回滚：子树级失效的边界与保守策略</h3>\n<p>回滚的粒度必须与失效粒度对齐。CodeMEM 按 AST 差异只失效受影响子树 KV，这带来一个工程陷阱：<b>跨多子树编辑时失效范围扩大</b>，若仍按单子树假设估算重算量，会低估迭代轮次的实际延迟。更严重的是，若失效判定遗漏了跨文件调用边（例如编辑改变了函数签名但未触及调用点节点），被保留的调用点 KV 会与新的定义语义不一致，形成<b>陈旧 KV 污染</b>——这类错误在后续轮次持续传播，且不触发任何失效事件。</p>\n<p>保守回滚策略是：当编辑触及节点满足 <code>indeg ≥ 2</code> 或存在跨文件出边时，把失效范围提升到“该节点 + 其直接调用点”，而非仅该子树。判定伪代码：<code>invalidate(n) = subtree(n) ∪ {c : edge(n→c) exists}</code>。推理系统代价上，这扩大了单轮重算量，但把陈旧 KV 的传播概率压到可接受范围；在 Blackwell 档位上，重算量增加意味着预填带宽占用上升，需与 KV 预算同步标定。监控上应记录“失效子树规模分布”与“跨文件边触发的额外失效次数”，后者突增说明仓库耦合度高，单子树假设不再成立。具体例子：修改工具函数签名，三处调用点虽未被编辑触及，但必须一并失效其 KV，否则下一轮预填会用旧签名语义拼接上下文，补丁在调用点处类型不匹配。</p>\n<p>回滚的最后一层是预算回退：当检测到降级节点中结构关键节点比例超阈值时，临时提高 <code>B_KV</code> 或降低摘要比例，待批次边界后恢复。这一操作必须记录在会话状态中，避免与并发会话的预算竞争叠加成全局 OOM。工程判断落在具体机制上：把“失效范围判定”与“预算回退”做成两个独立开关，前者按 AST 拓扑自动触发，后者按监控阈值人工或策略触发——两者耦合会在跨多子树编辑时同时放大重算量与显存占用，正是尾延迟与 OOM 并发的典型现场。</p>\n\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-44\">四十四 · 失效链诊断：从分数漂移到子树失效放大</h3>\n<p>CodeMEM 的失效不是单点故障，而是一条从价值分数漂移开始的链式反应。分数 <span class=\"formula\">$$s(n)=\\alpha\\,\\mathrm{indeg}(n)+\\beta\\,\\mathrm{ref}(n)+\\gamma\\,e^{-\\delta\\,\\mathrm{dist}(n)}$$</span> 中三项量纲不同，<span class=\"formula\">$$\\mathrm{indeg}$$</span> 是结构量、<span class=\"formula\">$$\\mathrm{ref}$$</span> 是跨轮累积量、编辑距离项随编辑次数指数衰减，权重为启发式设定且材料未给出数值。工程后果是：当一轮编辑把某函数从被三处调用改为被一处调用，入度项下降但 <span class=\"formula\">$$\\mathrm{ref}$$</span> 仍保留历史计数，节点可能维持完整驻留，占用本应让给新热点的 KV 预算。这类“分数滞后”不会报错，表现为前缀缓存命中率缓慢下滑、填充 token 比例上升——即静默降级。监控上应把每轮迭代的节点驻留状态变更（升级/降级/淘汰）计数与分数三项分量分别打点，而不是只看总命中率；一旦某节点的 <span class=\"formula\">$$\\mathrm{indeg}$$</span> 分量下降而驻留状态未变，即为漂移信号。</p>\n<p>第二类失效是摘要比例与重算成本的倒挂。摘要节点在预填阶段重算十余 token 并写回缓存，完整节点直接复用 KV。设一轮预填中完整节点数为 <span class=\"formula\">$$N_f$$</span>、摘要节点数为 <span class=\"formula\">$$N_s$$</span>、摘要平均重算 token 为 <span class=\"formula\">$$t_s$$</span>，则相对全量重算的节省近似为 <span class=\"formula\">$$\\frac{N_f \\cdot \\bar{t}_f}{N_f \\cdot \\bar{t}_f + N_s \\cdot t_s}$$</span>，其中 <span class=\"formula\">$$\\bar{t}_f$$</span> 为完整节点平均长度。当摘要比例升高或 <span class=\"formula\">$$t_s$$</span> 设置过大，分母中重算项膨胀，节省率趋近于零，而摘要 token 过小又会丢失定义—调用语义导致生成质量塌陷。这是一个无实验数字可依的权衡，部署时必须按 SLO 标定摘要比例：低延迟补全场景应压低摘要比例、优先完整驻留；中等吞吐批处理可提高摘要比例换取更多节点进入预算。监控项应含“摘要重算 token 占比”与“摘要节点后续被引用次数”，后者高说明摘要粒度切错了。</p>\n<p>第三类失效是跨多子树编辑下的失效范围放大。系统按 AST 差异只失效受影响子树 KV，单子树编辑时重算量可控；但一次重构触及函数体、三处调用点与上游导入节点时，失效子树从一棵变为多棵，若容量规划仍按单子树假设估算每轮重算量，实际尾延迟会显著超出预期。批调度器按驻留状态做变长序列打包，打包粒度受 AST 拓扑序约束，失效子树增多会打散原本连续的打包段，填充 token 比例与显存碎片同时上升，严重时触发 OOM——尤其在 KV 预算按硬件档位配置、驻留比例未随 NVFP4/FP8 精度选择调整的情况下。定位手段是按请求记录失效子树棵数与失效节点总 token 数，与预算上限做比值；该比值持续走高即为容量规划失配。回滚策略应落在预算参数而非代码路径：将摘要比例与驻留上限回退到上一稳定档位，强制对高入度节点保留完整驻留，并把变长打包切回按拓扑序的保守分段，可在不中断会话的前提下把尾延迟拉回 SLO 包络内。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>系统代价</th><th>回滚动作</th></tr></thead><tbody><tr><td>分数漂移</td><td>入度分量降而驻留未降</td><td>缓存命中率下滑、填充比例升</td><td>重算分数并强制降级</td></tr><tr><td>摘要倒挂</td><td>重算 token 占比升</td><td>预填前向增加、节省率趋零</td><td>压低摘要比例</td></tr><tr><td>失效放大</td><td>失效子树棵数与 token 比高</td><td>尾延迟超包络、OOM 风险</td><td>回退预算档位、保守打包</td></tr></tbody></table>\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-45\">四十五 · 评测口径的三层锚点：模型、硬件档位、负载形态</h3>\n<p>读 CodeMEM 这类记忆管理工作的数字，第一步不是看吞吐涨了多少，而是先确认三件事有没有对齐：模型、硬件档位、负载形态。三者任一漂移，横向比较就失去意义。CodeMEM 的记忆价值分数与 KV 驻留比例是推理期策略，不涉及权重改动，因此它对模型是“外挂式”的——同一套驻留策略套在 7B 与 70B 上，KV 预算的绝对字节数差一个数量级以上，命中率与重算占比也随之改变。材料未给出所用模型规格，这意味着任何“提升百分比”都无法跨模型外推。</p>\n<p>硬件档位同理。B200 与 GB200 NVL72 的差别不只是单卡 HBM 容量，而是 NVL72 机柜内 NVLink 5 域把 72 个 GPU 的显存连成可寻址池，KV 驻留集合可以跨卡分布，节点级淘汰的代价从“本地显存不足”变成“跨域搬运”。材料明确写“硬件档位与并行拓扑未给出，部署需按 B200／B300／GB200 NVL72 档位标定 KV 预算”，这句话的工程含义是：CodeMEM 的预算参数 B_KV 不是常量，而是档位函数。在单卡 B200 上，B_KV 受 HBM 上限与同时驻留会话数挤压；在 NVL72 上，B_KV 可放大但受 NVLink 带宽与跨卡失效同步延迟约束。</p>\n<p>负载形态是第三层。CodeMEM 的负载是“多会话并行迭代，每会话独立 AST 记忆状态”，这与单轮离线批推理的负载曲线完全不同：前者是长尾、低并发、编辑事件驱动的混合流，后者是可预测的满批。把 CodeMEM 的吞吐数字与满批离线推理的吞吐数字并列，等于拿变长打包的碎片化批和规整批比，不可比。</p>\n<div class=\"formula\">$$\\text{可比性} = f(\\text{模型规格},\\ \\text{硬件档位},\\ \\text{并发形态},\\ \\text{编辑频率})$$</div>\n<p>具体例子：假设两个部署都用 B200 单卡、同一 30B 级模型，A 部署 8 个并发会话、编辑间隔 30 秒，B 部署 64 个并发会话、编辑间隔 3 秒。B 的编辑频率高，AST 差异失效触发更频繁，前缀缓存命中率被反复打断；A 的会话少，驻留集合稳定，命中率高。此时 A 的 TTFT 更低不代表 CodeMEM 机制更优，只代表负载更温和。读数字必须先还原这组坐标。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-46\">四十六 · 指标族：TTFT、TPOT、吞吐、显存、功耗各自度量什么</h3>\n<p>CodeMEM 的机制同时作用于预填与解码两个阶段，因此指标必须分阶段读。预填阶段的核心指标是 TTFT（首 token 延迟），它由三块构成：AST 解析与依赖图构建的前置延迟、完整驻留节点的前缀缓存查表、摘要节点的少量 token 重算。材料写“AST 解析与依赖图构建为请求前置步骤，超大仓库下预处理延迟未给出”，这意味着 TTFT 中有一块未标定的固定开销，且它随仓库规模增长。任何声称 TTFT 下降的数字，若未剥离解析开销，就无法判断下降来自缓存命中还是来自仓库变小。</p>\n<div class=\"formula\">$$\\mathrm{TTFT} \\approx T_{\\text{parse}} + T_{\\text{cache-hit}} + T_{\\text{summary-recompute}} + T_{\\text{first-decode}}$$</div>\n<p>解码阶段的指标是 TPOT（每输出 token 时间）。CodeMEM 对 TPOT 的影响是间接的：完整驻留节点复用 KV，解码时无需重算其注意力键值；摘要节点在预填时已重算并写回缓存，解码阶段走常规路径。因此 TPOT 的改善主要来自“预填序列变短、批内填充减少”，而非解码算子本身。材料未给出量化，工程上应把 TPOT 拆成“批内有效 token 占比”来看——变长打包降低填充浪费，直接抬高有效 token 占比，TPOT 随之下降。</p>\n<p>吞吐指标要区分两种口径：会话吞吐（每秒完成的迭代轮次）与 token 吞吐（每秒生成 token）。CodeMEM 的增量失效让未触及节点继续驻留，第二轮迭代的重算量下降，会话吞吐受益；但摘要节点重算引入额外前向，token 吞吐可能被侵蚀。材料写“摘要比例升高时重算成本可能侵蚀缓存收益”，这正是两个吞吐口径分叉的地方。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>主要受什么影响</th><th>CodeMEM 的作用点</th><th>读数的陷阱</th></tr></thead><tbody><tr><td>TTFT</td><td>解析 + 缓存命中 + 摘要重算</td><td>子树级失效减少整段重算</td><td>解析开销未剥离则不可比</td></tr><tr><td>TPOT</td><td>批内有效 token 占比</td><td>变长打包降填充</td><td>与解码算子优化混淆</td></tr><tr><td>会话吞吐</td><td>每轮重算量</td><td>未失效节点继续驻留</td><td>编辑频率不同则不可比</td></tr><tr><td>token 吞吐</td><td>摘要重算额外前向</td><td>摘要比例越高越吃亏</td><td>与满批离线吞吐并列即错</td></tr><tr><td>显存</td><td>驻留集合大小 + 碎片</td><td>节点级升降级</td><td>档位不同 B_KV 不同</td></tr><tr><td>功耗</td><td>重算前向次数 + 驻留占用</td><td>减少整段重算降功耗</td><td>未给数据，只能定性</td></tr></tbody></table>\n<p>显存指标要按“驻留字节 + 碎片字节”两项读。节点可在摘要与完整驻留间升降级，预算竞争导致部分节点被淘汰，淘汰与提升造成驻留集合抖动，抖动本身产生显存碎片。材料写“需监控填充 token 比例与显存碎片”，说明碎片是独立监控项，不能只看总占用。功耗指标材料完全未给，只能定性：整段重算被子树失效替代，减少的前向次数对应功耗下降；但摘要重算是新增前向，两者相抵后的净值需实测。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-47\">四十七 · batch 与并发：变长打包如何改变可比性</h3>\n<p>CodeMEM 的批调度器按节点驻留状态做变长序列打包，这是它区别于常规连续批处理的地方。常规连续批处理按请求到达顺序拼接，填充 token 由最长序列决定；CodeMEM 按 AST 拓扑序与驻留状态排序，把完整驻留节点排在前面、摘要节点排在后面，使同批内序列长度更接近。填充浪费下降的直接收益是显存与算力利用率上升，但代价是打包粒度受 AST 拓扑序约束——依赖链上的节点不能随意重排，排序自由度受限。</p>\n<p>并发口径的关键是“每会话独立 AST 记忆状态”。多会话并行时，每个会话维护自己的驻留集合，会话间不共享 KV。这意味着并发数上升时，显存需求近似线性增长，而不是像共享前缀缓存那样次线性增长。材料写“并发形态为多会话并行迭代，每会话维护独立 AST 记忆状态与 KV 驻留集合”，工程判断是：CodeMEM 的并发扩展性受显存而非算力约束，在 B200 单卡上并发数上限由 B_KV 除以单会话驻留均值决定。</p>\n<div class=\"formula\">$$N_{\\text{concurrent}} \\le \\frac{B_{\\mathrm{KV}}^{\\text{device}}}{\\mathbb{E}[\\text{resident bytes per session}]}$$</div>\n<p>具体例子：一次仓库级修复请求，首轮该函数节点入度为三、跨文件引用两次，分数最高，分配完整 KV 驻留；上游导入节点仅保留摘要 token。预填时完整节点命中前缀缓存，摘要节点重算十余 token。若此时同批还有三个会话，各自驻留集合不同，打包器需按四组拓扑序交错排列，填充比例取决于四组序列长度的离散度。第二轮用户追加“再补一个边界检查”，调用点节点因新引用分数上升被提升为完整驻留，预填序列重排并重新打包——重排本身是一次调度开销，材料未量化，但它是并发场景下不可忽略的抖动源。</p>\n<p>读 batch 相关数字时，必须问清楚：批大小是固定还是变长、填充比例多少、打包是否跨会话。固定批的吞吐数字与变长打包的吞吐数字不可直接比，因为前者分母含填充 token，后者分母是有效 token。CodeMEM 的机制价值恰在降低填充，因此它的吞吐数字若按“有效 token/秒”报，会比按“总 token/秒”报更有利——两种口径的差距就是填充比例。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-48\">四十八 · 哪些提升不可比：四类典型错配</h3>\n<p>第一类错配是基线与机制不同层。材料明确“材料未给出对比基线”。若有人拿 CodeMEM 与“全量保留 KV”比，赢在显存；与“固定窗口截断”比，赢在依赖链保留；这两个基线各自输在不同维度，把两组提升百分比并列求平均没有意义。CodeMEM 的定位是把“截断或全留”的二选一推进到结构感知的预算分配，它的正确对照是“同等显存预算下的截断策略”，而非无预算约束的全量保留。</p>\n<p>第二类错配是编辑频率不同。增量失效的收益与编辑事件频率强相关：编辑越频繁，整段重算被替代的次数越多，收益越大；编辑稀疏时，前缀缓存本就长期有效，CodeMEM 的子树失效优势被稀释。两个部署若编辑间隔差一个数量级，命中率提升数字不可比。材料写“编辑事件频繁，需按 AST 差异触发增量失效”，这提示收益场景是高频编辑的 agent 循环，而非一次性生成。</p>\n<p>第三类错配是摘要比例不同。摘要节点重算是新增成本，摘要比例越高，重算 token 越多，缓存收益被侵蚀越多。材料写“摘要 token 数量设置过小会丢失定义—调用语义，过大则重算成本抵消缓存收益”，这是一个双向陷阱：报出的提升数字若未标注摘要比例，读者无法判断它处在权衡曲线的哪一侧。两个摘要比例不同的配置，其 TTFT 与吞吐数字不可比。</p>\n<p>第四类错配是失效粒度假设不同。材料写“跨多子树编辑时失效范围扩大，若仍按单子树假设估算重算量，会低估迭代轮次的实际延迟”。这意味着按单子树编辑标定出的重算量，在多子树编辑场景下系统性偏低。若一个部署的编辑多为跨文件重构（触及多个子树），另一个多为单函数修补，两者的实际延迟差可能远超机制本身的差异。</p>\n<table class=\"mini\"><thead><tr><th>错配类型</th><th>表现</th><th>工程判断</th></tr></thead><tbody><tr><td>基线不同层</td><td>与全量保留比显存、与截断比依赖链</td><td>只与同预算截断策略对照</td></tr><tr><td>编辑频率</td><td>高频编辑收益大，稀疏编辑收益小</td><td>标注编辑间隔再比</td></tr><tr><td>摘要比例</td><td>比例不同则重算成本不同</td><td>标注摘要 token 占比再比</td></tr><tr><td>失效粒度</td><td>多子树编辑低估延迟</td><td>按编辑跨度分布标定</td></tr></tbody></table>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-49\">四十九 · 数字怎么读：从机制到可核验量的映射</h3>\n<p>材料未给出任何可核验的实验数字，因此本部分的读法是“建立映射”，而非“引用结论”。CodeMEM 的每个机制都对应一个可观测的中间量，部署时应先采这些中间量，再看端到端指标。前缀缓存命中率对应完整驻留节点的复用比例；摘要重算 token 占比对应两级上下文供给的成本侧；失效子树规模对应增量失效的收益侧；填充 token 比例对应变长打包的效率；显存碎片对应驻留集合抖动的代价。材料把这些列为监控项，正是提示端到端数字必须由这些中间量解释。</p>\n<div class=\"formula\">$$\\text{净收益} \\approx \\underbrace{\\Delta T_{\\text{recompute-avoided}}}_{\\text{子树失效收益}} - \\underbrace{\\Delta T_{\\text{summary-recompute}}}_{\\text{摘要重算成本}} - \\underbrace{T_{\\text{parse}}}_{\\text{解析前置}}$$</div>\n<p>具体例子：第二轮迭代中，调用点节点因新引用分数上升被提升为完整驻留，预填序列重排。此时可观测的是：命中率因提升而上升、重排导致的打包抖动使填充比例短暂上升、摘要重算 token 因部分节点升级而下降。三个中间量方向不一致，端到端 TTFT 的净变化取决于三者相对大小。若只报端到端数字，读者无法判断是机制有效还是负载碰巧温和。</p>\n<p>功耗维度同样只能定性映射：整段重算被子树失效替代，减少的前向次数对应功耗下降；摘要重算是新增前向，两者相抵。材料未给功耗数据，工程上应把“每轮重算前向次数”作为功耗的代理指标，而非直接报瓦特数。在 GB200 NVL72 机柜尺度上，功耗还受跨卡 KV 搬运影响，节点淘汰若触发跨域迁移，NVLink 5 上的搬运功耗会进入账单，这一项材料未涉及但部署时必须计入。</p>\n<p>最后一条读法是“档位标定优先于横向比较”。材料反复写“KV 预算按硬件档位配置”“部署需按档位标定预算与摘要比例”，这意味着 CodeMEM 没有一组通用最优参数。B200 单卡上应优先压低摘要比例以省显存，GB200 NVL72 上可放大驻留集合并用跨卡分布摊薄淘汰代价。同一机制在不同档位上的最优参数不同，跨档位的提升百分比因此不可比——这正是本部分要守住的读数字底线：先对齐坐标，再谈数字。</p>\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-50\">五十 · 迁移到非代码领域：AST 锚点消失后还剩什么</h3>\n<p>CodeMEM 的全部预算分配逻辑挂在一棵显式的语法树上：节点边界由解析器给出，依赖边由定义—调用—导入关系标注，编辑差异由子树比对定位。这套机制迁到别的领域，第一件事不是改权重，而是问“锚点还在不在”。自然语言长文档有章节树、有段落边界，但段落之间没有定义—调用这种硬依赖边，入度项 <code>indeg(n)</code> 退化为零或需要另造语义链接；对话历史有轮次结构，但轮次之间的引用关系是隐式的、由模型自行判断的，无法在解析阶段确定。因此迁移的第一类改动是把依赖边从“语法解析可得”换成“检索或聚类推断可得”，代价是边本身带噪声，价值分数不再可信到可以直接排序拼接。</p>\n<p>可行的折中是保留结构骨架、放弃精确边权。章节树、函数调用图、工具调用链这类层级结构在多数领域都存在，可以作为节点划分依据；依赖强度改用共现频次或检索相似度近似，公式退化为</p>\n<div class=\"formula\">$$s(n)=\\beta\\,\\mathrm{ref}(n)+\\gamma\\,e^{-\\delta\\,\\mathrm{dist}(n)}+\\varepsilon\\,\\mathrm{sim}(n,q)$$</div>\n<p>其中 <code>sim</code> 项替代入度，权重 <code>ε</code> 需按领域重新标定。系统代价直接体现在前缀缓存命中率上：语法边稳定时，编辑只失效子树，命中率高；语义边随查询漂移时，节点驻留集合每轮都在变，缓存复用率下降，变长打包的填充比例上升。一个具体例子是长文档问答：用户连续追问同一份合同的不同条款，条款间没有调用关系，只有引用关系，按相似度打分的节点在追问切换时会整体升降级，预填序列重排导致打包碎片化，吞吐收益被抵消。判断是：AST 锚点是这套方案的核心资产，锚点退化为软结构时，收益从“缓存命中”转向“预算可控”，前者不再成立。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-51\">五十一 · 迁到别的模型：KV 布局与失效粒度的耦合</h3>\n<p>CodeMEM 的增量失效假设 KV 条目可以按节点边界切分并单独丢弃。这在标准多头注意力、连续 KV 布局下成立，因为 token 位置与 KV 槽位一一对应，子树失效等价于丢弃一段连续槽位。迁到 GQA/MQA 时，KV 头数减少但槽位仍按 token 排列，切分逻辑不变，只是每节点占用的显存下降，预算 <code>B_KV</code> 可容纳更多完整驻留节点，摘要比例可下调。迁到 MLA 这类把 KV 压缩为低秩潜向量的结构时，槽位与 token 的对应关系仍在，但单节点 KV 体积变小、压缩后语义边界模糊，子树失效的收益变小而重算成本不变，两级供给的经济性需要重算。</p>\n<p>真正不适用的是把 KV 跨层或跨 token 混合存储的方案，例如把 KV 量化后按块共享、或把多层 KV 折叠成统一缓存。这类布局下节点边界与存储块边界不对齐，按子树失效会连带丢弃未受影响节点的 KV，失效粒度被迫放大到块级，增量失效退化为整段重算。系统代价是显存带宽：块级失效意味着每轮迭代要重新写入更大范围的 KV，带宽占用上升，低延迟补全的 SLO 被击穿。工程判断是迁移前先确认三件事——KV 是否按 token 连续布局、节点边界是否落在对齐边界上、失效后是否需要重写相邻块。三者任一不满足，就应放弃子树级失效，退回按轮次整体重建，并相应放宽 SLO。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-52\">五十二 · 规模上限：解析开销与预算竞争的交叉点</h3>\n<p>规模上限不在 KV 预算，而在前置解析。AST 解析与依赖图构建是每请求前置步骤，成本随仓库文件数与跨文件边数增长，且与生成长度无关——也就是说，短补全请求要为整仓库解析付费。设解析耗时为 <code>T_parse(|R|)</code>，解码耗时为 <code>T_dec(L)</code>，则端到端延迟中解析占比随请求变短而上升。当 <code>T_parse</code> 超过补全 SLO 的余量时，方案失效，与 KV 省了多少无关。缓解手段是增量解析：只对编辑触及的文件重解析，其余复用上一轮依赖图，但跨文件边在编辑后可能新增或删除，增量解析需要做边的一致性校验，校验成本随受影响文件数增长。</p>\n<p>第二个上限来自预算竞争的饱和。节点数随仓库规模线性增长，而 <code>B_KV</code> 固定，分数排序后大量低分节点被压成摘要，摘要比例升高使重算 token 总量上升。重算成本近似为</p>\n<div class=\"formula\">$$C_{\\mathrm{recalc}}\\approx \\rho\\cdot N_{\\mathrm{sum}}\\cdot \\bar{t}_{\\mathrm{sum}}$$</div>\n<p>其中 <code>ρ</code> 为摘要节点比例，<code>N_sum</code> 为摘要节点数，<code>t_sum</code> 为单节点摘要 token 数。仓库翻倍时 <code>N_sum</code> 翻倍，若 <code>B_KV</code> 不变则 <code>ρ</code> 上升，重算成本超线性增长，缓存收益被侵蚀。具体例子是万级文件的单体仓库：函数节点数十万，预算只能容纳极小比例完整驻留，绝大多数节点走摘要重算，预填阶段实际做的是一次大范围轻量前向，前缀缓存命中率虽高但重算量已接近全量重算，方案退化为“带结构的截断”。判断是：规模上限由 <code>B_KV</code> 与仓库节点数的比值决定，比值低于某阈值时摘要重算成本吞掉收益，此时应改用分层策略——只对当前编辑路径上的节点建图，其余文件按需惰性解析。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-53\">五十三 · 编辑形态的边界：单子树假设何时破产</h3>\n<p>增量失效的收益建立在“编辑只触及单个子树”的假设上。重命名一个跨十处调用的公共符号、批量替换接口签名、迁移目录结构，这三类编辑会同时触及多个不相交子树，失效范围按子树并集扩大。设失效子树集合为 <code>S</code>，重算量为各子树 KV 之和，若 <code>S</code> 覆盖了预算内多数完整驻留节点，本轮迭代等价于整段重算，且比整段重算更差——因为还要额外付出 AST 差异比对与驻留状态重排的开销。</p>\n<p>边界判断可以写成阈值：当失效子树占用 KV 超过预算的某一比例时，放弃增量路径、直接整体重建更划算。这个比例取决于重建的固定开销与增量路径的比对开销之比，材料未给出数值，部署时需实测。系统代价体现在批调度上：跨多子树编辑后，多个会话的驻留集合同时重排，变长打包的序列长度分布突变，填充 token 比例上升，吞吐短时下跌。具体例子是接口签名批量替换：三处调用点与定义节点同时失效，若仍按单子树假设估算重算量，实际延迟被低估，SLO 违约出现在编辑落地后的第一轮预填而非解码阶段。工程上应把“编辑影响面估计”作为独立监控项，在失效范围超阈值时切到重建路径。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-54\">五十四 · 硬件档位与精度选择对驻留比例的反向约束</h3>\n<p>迁移到不同 Blackwell 档位时，可调的不是机制而是驻留比例。B200 与 B300 的显存容量差异直接改变 <code>B_KV</code> 的绝对值，GB200 NVL72 的机架级显存则允许把预算放大到跨节点共享，但跨节点共享 KV 引入通信代价：节点驻留集合若分布在多个 GPU 上，预填拼接需要跨卡搬运 KV，NVLink 带宽成为新的瓶颈。此时“完整驻留”不再是免费的，驻留比例的上限由跨卡搬运带宽而非显存容量决定。</p>\n<p>精度选择反向约束摘要策略。KV 走 FP8 时单节点体积减半，预算可容纳更多完整节点，摘要比例下调，重算成本下降；走 NVFP4 时体积进一步压缩，但低精度 KV 对定义—调用语义的保真度下降，摘要节点若也用低精度重算，语义丢失风险上升，需对高价值子树保留高精度 KV、对摘要节点用低精度，形成精度分层。系统代价是显存带宽与功耗：精度分层意味着同一预填序列内混合精度 KV，搬运与反量化开销上升，功耗随重算比例上升。判断是：精度越低，越应提高完整驻留比例以抵消语义损失，这与“精度低所以多存”的直觉一致，但与“精度低所以多摘要省显存”的直觉相反，部署时容易搞反。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-55\">五十五 · 不适用的场景与迁移检查清单</h3>\n<p>三类场景明确不适用。第一类是单文件、无跨文件依赖的补全请求：AST 图退化为单棵树，入度项为零，分数只剩引用频次与编辑距离，机制与固定窗口截断无本质差别，却多付解析开销。第二类是生成与仓库结构无关的任务，例如根据自然语言描述从零写脚本，没有既有依赖图可依，节点价值分数无信息量。第三类是编辑频率极高、每轮几乎重写全部上下文的会话，失效范围持续覆盖预算内多数节点，增量路径的比对开销纯属浪费。</p>\n<p>迁移检查清单按顺序执行：确认目标领域存在可解析的层级结构且节点边界与 KV 槽位对齐；确认编辑形态以局部修改为主、跨子树编辑占比低；确认解析延迟占 SLO 余量的比例可接受，必要时启用惰性解析；确认 <code>B_KV</code> 与节点数的比值高于摘要重算成本吞掉收益的阈值；确认精度选择与驻留比例的方向没有搞反。五项中任一不满足，就应把方案降级为“结构感知的截断 + 轮次级重建”，保留预算可控性、放弃缓存命中收益。这套方案的价值在于把显存代价与结构依赖显式挂钩，迁移时真正要搬的是这个挂钩关系，而不是分数公式本身；挂钩关系在软结构领域失效时，剩下的只是一个可调的预算排序器，收益上限由排序质量而非缓存复用决定。</p>\n\n<h3 id=\"paper-codemem-ast-guided-adaptive-memory-f-2026-sec-56\">五十六 · 迁移边界：AST 记忆方案在何种模型与仓库形态下失效</h3>\n<p>这套方案的可迁移性取决于两个前提是否成立：模型侧必须支持前缀缓存与变长打包，且解码对上下文顺序不敏感；仓库侧必须存在稳定、可解析的语法结构。迁到不支持前缀缓存复用的推理栈（例如某些自定义 attention 后端或强制连续批处理填充的实现），完整驻留节点的 KV 复用直接归零，只剩摘要重算一条路径，两级供给退化为单级，方案的全部收益消失。迁到非代码领域同样受限：自然语言长文没有定义—调用边，AST 依赖图无法构建，价值分数三项中 indeg 与 dist 失去语义，只剩引用频次一项，等价于退化为粗糙的 LRU，而 LRU 在长文档问答上并不优于分块检索。判断标准很直接——若领域内不存在显式的符号引用关系，就不要引入这套打分。</p>\n<p>规模上限由预处理与失效范围共同决定。AST 解析与依赖图构建是每请求前置步骤，代价随仓库文件数与跨文件边数增长，记为 <span class=\"formula\">$$T_{\\mathrm{prep}}\\approx c_1 N_{\\mathrm{file}}+c_2 E_{\\mathrm{edge}}$$</span>，而低延迟补全的 SLO 预算通常只有数百毫秒量级，仓库规模一旦使该项逼近预算，方案在交互式场景就不可用，只能退化为按目录懒解析。另一侧是失效放大：一次跨 k 个子树的编辑，失效代价近似 <span class=\"formula\">$$C_{\\mathrm{inv}}\\approx\\sum_{i=1}^{k}\\left(T_{\\mathrm{recalc}}(n_i)+T_{\\mathrm{reparse}}(n_i)\\right)$$</span>，当 k 随重构类请求增大时，子树级失效的总量可能超过整段重算，此时增量策略反成负收益。工程上应以监控项“失效子树规模”设阈值，超过即回退整段重算。</p>\n<p>下表给出迁移判断的边界条件，而非普适结论。</p>\n<table class=\"mini\"><thead><tr><th>迁移目标</th><th>需改动</th><th>失效条件</th></tr></thead><tbody><tr><td>无前缀缓存的推理栈</td><td>需自建节点级 KV 池与索引</td><td>复用率为零，收益消失</td></tr><tr><td>非代码长文本</td><td>依赖图退化为引用计数</td><td>无符号边，打分失真</td></tr><tr><td>超大单体仓库</td><td>懒解析＋目录级预算</td><td>预处理延迟超 SLO</td></tr><tr><td>高频重构会话</td><td>失效阈值＋整段回退</td><td>跨多子树编辑放大代价</td></tr></tbody></table>\n<p>还有一处硬边界在预算竞争：分数为启发式加权且权重未标定，节点在摘要与完整驻留间的升降级由 <span class=\"formula\">$$\\sum_{n\\in R}s(n)\\le B_{\\mathrm{KV}}$$</span> 的排序截断决定，预算收紧时被淘汰的往往是低频但语义关键的导入节点，导致定义—调用链在下一轮断裂。迁到不同精度档位（NVFP4 与 FP8 的 KV 占用不同）时必须重标定预算与摘要比例，否则同一套权重在不同硬件上给出不同的驻留集合，行为不可复现。结论是：这套方案适合符号结构清晰、编辑局部性强、且推理栈支持前缀复用的仓库级迭代场景；对无结构领域、超大仓库的强交互补全、以及跨子树高频重构，应明确判定为不适用，而不是靠调参硬撑。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">CodeMEM: AST-Guided </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Adaptive Memory for…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2026 · arXiv preprint</text></svg><figcaption><b>家谱</b> · CodeMEM: AST-Guided Ada… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>材料未给出具体数据集名称与规模</td></tr><tr><td>基线</td><td>材料未给出对比基线</td></tr><tr><td>主要结果</td><td>材料未给出可核验的实验数字；论文卡仅描述机制层面的 KV 预算分配与增量失…</td></tr><tr><td>消融</td><td>材料未给出消融实验；分数权重、摘要 token 数量与失效粒度三者的影响均…</td></tr><tr><td>局限</td><td>材料未给出评测边界；从机制看，AST 解析开销随仓库规模增长，摘要节点重算…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-codemem-ast-guided-adaptive-memory-f-2026 · 共 9 个片段</p>\n";break;}}})();
